    pathlib.Path(td+"/data/applications/test.desktop").write_text(f"[Desktop Entry]\nType=Application\nName=TestApp\nExec={script} %f\nMimeType=text/plain;\n")
    def run(args):
        r=subprocess.run([EXE]+args,capture_output=True,text=True,env=env); time.sleep(0.1)
