        if pathlib.Path(out).exists(): pathlib.Path(out).unlink()
        print(" ",args, r.returncode, repr(r.stderr), "out:",o); return r
    for s in extra_sets: run(["set",s,"test.desktop"])
    p=pathlib.Path(td+"/file.txt"); p.write_text("hello\n")
