TOKEN_CHARS = set(b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!#$%&'*+-.^_`|~")

class MimeKey:
    __slots__ = ('typ', 'sub', 'params')
    def __init__(self, typ, sub, params=()):
        self.typ = typ
        self.sub = sub
        self.params = tuple(params)
    def essence(self):
        return "%s/%s" % (self.typ, self.sub)
    def canonical(self):
        s = self.essence()
        for (k, v) in self.params:
            s += "; %s=%s" % (k, v)
        return s
    def __eq__(self, other):
        return isinstance(other, MimeKey) and self.typ == other.typ and self.sub == other.sub and self.params == other.params
    def __hash__(self):
        return hash((self.typ, self.sub, self.params))
    def __repr__(self):
        return 'MimeKey(%r)' % self.canonical()

def _mime_invalid(bts, pos):
    return "mime parse error: an invalid token was encountered, %X at position %d" % (bts[pos], pos)

def parse_mime_str(s):
    """Return (MimeKey or None, error string or None).
    If subtype is empty and string ends there, returns MimeKey with sub='' and
    error None (the validator turns this into `bad mime:`)."""
    try:
        bts = s.encode('utf-8')
    except Exception:
        bts = os.fsencode(s)
    n = len(bts)
    i = 0
    # type
    while i < n:
        b = bts[i]
        if b == 0x2f:  # /
            if i == 0:
                return None, _mime_invalid(bts, i)
            break
        if b not in TOKEN_CHARS:
            return None, _mime_invalid(bts, i)
        i += 1
    if i >= n:
        return None, "mime parse error: a slash (/) was missing between the type and subtype"
    typ = bts[:i].decode('ascii', 'replace').lower()
    sub_start = i + 1
    i = sub_start
    while i < n:
        b = bts[i]
        if b == 0x3b:  # ;
            break
        if b not in TOKEN_CHARS:
            return None, _mime_invalid(bts, i)
        i += 1
    sub = bts[sub_start:i].decode('ascii', 'replace').lower()
    if sub == '':
        if i < n:
            return None, _mime_invalid(bts, i)
        return MimeKey(typ, '', ()), None
    params = []
    # i at ';' or end
    while i < n:
        # bts[i] == ';'
        i += 1
        while i < n and bts[i] in (0x20, 0x09):
            i += 1
        if i >= n:
            break
        name_start = i
        while i < n:
            b = bts[i]
            if b == 0x3d:  # =
                break
            if b not in TOKEN_CHARS:
                return None, _mime_invalid(bts, i)
            i += 1
        if i >= n:
            return None, "mime parse error: an equals sign (=) was missing between a parameter and its value"
        if i == name_start:
            return None, _mime_invalid(bts, i)
        pname = bts[name_start:i].decode('ascii', 'replace').lower()
        i += 1  # =
        if i < n and bts[i] == 0x22:  # quote
            i += 1
            vstart = i
            # find closing quote
            j = bts.find(b'"', i)
            if j == -1 or j == vstart:
                return None, 'mime parse error: a quote (") was missing from a parameter value'
            pval = bts[vstart:j].decode('utf-8', 'replace')
            i = j + 1
            if i < n and bts[i] != 0x3b:
                return None, _mime_invalid(bts, i)
            params.append((pname, pval))
            # i at ; or end, loop continues
        else:
            vstart = i
            while i < n:
                b = bts[i]
                if b == 0x3b:
                    break
                if b not in TOKEN_CHARS:
                    return None, _mime_invalid(bts, i)
                i += 1
            pval = bts[vstart:i].decode('utf-8', 'replace')
            params.append((pname, pval))
    return MimeKey(typ, sub, tuple(params)), None

