_glob_entries = None
_glob_aliases = None

def _mime_data_dirs():
    dirs = []
    dh = data_home_path()
    if dh:
        dirs.append(os.path.join(dh, 'mime'))
    for d in data_dirs_list():
        dirs.append(os.path.join(d, 'mime'))
    return dirs

def _glob_match(pattern, name):
    # translate glob to regex, * ? [seq]
    regex = ''
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '*':
            regex += '.*'
        elif c == '?':
            regex += '.'
        elif c == '[':
            j = pattern.find(']', i + 1)
            if j == -1:
                regex += re.escape(c)
            else:
                inner = pattern[i + 1:j]
                if inner.startswith('!'):
                    inner = '^' + inner[1:]
                regex += '[' + inner + ']'
                i = j
        else:
            regex += re.escape(c)
        i += 1
    return re.match('^' + regex + '$', name, re.DOTALL) is not None

def load_mime_globs():
    global _glob_entries, _glob_aliases
    if _glob_entries is not None:
        return _glob_entries, _glob_aliases
    entries = []  # (weight, pattern, mime_str)
    aliases = {}
    order = 0
    for mdir in _mime_data_dirs():
        # aliases
        try:
            with open(os.path.join(mdir, 'aliases'), 'r', encoding='utf-8', errors='replace') as f:
                for line in f:
                    parts = line.split()
                    if len(parts) >= 2:
                        aliases[parts[0]] = parts[1]
        except OSError:
            pass
        # globs2
        got_globs2 = False
        try:
            with open(os.path.join(mdir, 'globs2'), 'r', encoding='utf-8', errors='replace') as f:
                for line in f:
                    line = line.rstrip('\n')
                    if not line or line.startswith('#'):
                        continue
                    parts = line.split(':')
                    if len(parts) >= 3:
                        try:
                            w = int(parts[0])
                        except Exception:
                            w = 50
                        entries.append((w, parts[1], parts[2], order)); order += 1
                        got_globs2 = True
        except OSError:
            pass
        # globs (v1)
        try:
            with open(os.path.join(mdir, 'globs'), 'r', encoding='utf-8', errors='replace') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#') or ':' not in line:
                        continue
                    mime, pattern = line.split(':', 1)
                    entries.append((50, pattern, mime, order)); order += 1
        except OSError:
            pass
        # packages xml
        pkgdir = os.path.join(mdir, 'packages')
        try:
            names = os.listdir(pkgdir)
        except OSError:
            names = []
        for name in names:
            if not name.endswith('.xml'):
                continue
            try:
                tree = ElementTree.parse(os.path.join(pkgdir, name))
            except Exception:
                continue
            for elem in tree.iter():
                tag = elem.tag
                if '}' in tag:
                    tag = tag.split('}', 1)[1]
                if tag != 'mime-type':
                    continue
                mtype = elem.get('type')
                if not mtype:
                    continue
                for child in elem:
                    ctag = child.tag
                    if '}' in ctag:
                        ctag = ctag.split('}', 1)[1]
                    if ctag == 'glob':
                        pattern = child.get('pattern')
                        if pattern:
                            try:
                                w = int(child.get('weight', '50'))
                            except Exception:
                                w = 50
                            entries.append((w, pattern, mtype, order)); order += 1
                    elif ctag == 'alias':
                        atype = child.get('type')
                        if atype:
                            aliases[atype] = mtype
    _glob_entries = entries
    _glob_aliases = aliases
    return entries, aliases

def guess_mime_by_filename(filename):
    if not filename:
        return None
    entries, aliases = load_mime_globs()
    if not entries:
        return None
    best = None
    # case sensitive first, then insensitive
    for insensitive in (False, True):
        candidates = []
        for (w, pattern, mstr, order) in entries:
            pat = pattern.lower() if insensitive else pattern
            name = filename.lower() if insensitive else filename
            if _glob_match(pat, name):
                candidates.append((w, len(pattern), -order, mstr))
        if candidates:
            candidates.sort(key=lambda x: (x[0], x[1], x[2]))
            best = candidates[-1][3]
            break
    if best is None:
        return None
    mk, err = parse_mime_str(best)
    if mk is None:
        return None
    # alias resolve
    ess = mk.essence()
    seen = set()
    while ess in aliases and ess not in seen:
        seen.add(ess)
        ess = aliases[ess]
        mk2, _ = parse_mime_str(ess)
        if mk2 is None:
            break
        mk = mk2
        ess = mk.essence()
    return mk

def rust_path_file_name(p):
    # Components split by '/', drop '' and '.', last component if '..' or none -> ''
    parts = []
    for comp in p.split('/'):
        if comp == '' or comp == '.':
            continue
        parts.append(comp)
    if not parts:
        return ''
    last = parts[-1]
    if last == '..':
        return ''
    return last

# ---------------------------------------------------------------------------
# Desktop entry parsing

class DesktopEntry:
    __slots__ = ('name', 'exec', 'mime_types', 'icon', 'terminal', 'path')
    def __init__(self, name, exec_, mime_types, icon, terminal, path):
        self.name = name
        self.exec = exec_
        self.mime_types = mime_types
        self.icon = icon
        self.terminal = terminal
        self.path = path

_desktop_parse_cache = {}

def parse_desktop_file(path):
    if path in _desktop_parse_cache:
        return _desktop_parse_cache[path]
    result = _parse_desktop_file_uncached(path)
    _desktop_parse_cache[path] = result
    return result

def _parse_desktop_file_uncached(path):
    try:
        with open(path, 'rb') as f:
            data = f.read()
    except OSError:
        return None
    try:
        text = data.decode('utf-8')
    except Exception:
        return None
    if text.startswith('\ufeff'):
        text = text[1:]
    sections = {}
    current = {}
    sections[''] = current
    raw_lines = text.split('\n')
    for raw in raw_lines:
        line = raw[:-1] if raw.endswith('\r') else raw
        eff = line.lstrip(' \t')
        if eff.strip(' \t') == '':
            continue
        if eff.startswith('#'):
            continue
        if eff.startswith('['):
            trimmed = eff.rstrip(' \t')
            if not trimmed.endswith(']'):
                return None
            inner = trimmed[1:-1]
            if inner == '':
                return None
            current = {}
            sections[inner] = current
            continue
        if '=' not in eff:
            return None
        key, value = eff.split('=', 1)
        current[key] = value
    desktop = sections.get('Desktop Entry')
    if desktop is None:
        return None
    name = desktop.get('Name')
    exec_ = desktop.get('Exec')
    if not name or not exec_:
        return None
    mime_types = []
    if 'MimeType' in desktop:
        mv = desktop.get('MimeType') or ''
        for seg in mv.split(';'):
            if seg == '':
                continue
            mk, err = parse_mime_str(seg)
            if mk is not None:
                mime_types.append(mk)
    return DesktopEntry(name, exec_, mime_types, desktop.get('Icon'), desktop.get('Terminal') == 'true', path)

def join_handler_candidate(app_dir, handler):
    if os.path.isabs(handler):
        return handler
    return os.path.join(app_dir, handler)

def lookup_desktop(handler):
    """Returns (candidate_path or None, entry or None). candidate set if exists."""
    for app_dir in application_dirs():
        cand = join_handler_candidate(app_dir, handler)
        if os.path.exists(cand):
            entry = parse_desktop_file(cand)
            return cand, entry
    return None, None

