PANIC_DESKTOP_REMOVE = ("src/common/desktop_entry.rs:105:18", "removal index (is 0) should be < len (is 0)")
PANIC_CONFIG_UNWRAP = ("src/config.rs:77:58", "called `Option::unwrap()` on a `None` value")
PANIC_CONFIG_REMOVE = ("src/config.rs:78:38", "removal index (is 0) should be < len (is 0)")

def tokenize_exec(s, panic_site=PANIC_DESKTOP_UNWRAP):
