DEFAULT_SELECTOR = "rofi -dmenu -i -p 'Open With: '"
DEFAULT_CONFIG_TEXT = 'enable_selector = false\nselector = "rofi -dmenu -i -p \'Open With: \'"\n'

class ConfigObj:
    def __init__(self):
        self.enable_selector = False
        self.selector = DEFAULT_SELECTOR
        self.cfg_dir = None
        self.mimeapps_path = None

# ---- minimal TOML parsing (sufficient for handlr config files) ----

class TomlError(Exception):
    def __init__(self, debug_text):
        self.debug_text = debug_text

def _toml_type_name(v):
    if isinstance(v, bool):
        return 'boolean `%s`' % ('true' if v else 'false')
    if isinstance(v, str):
        return 'string "%s"' % v
    if isinstance(v, int):
        return 'integer `%d`' % v
    if isinstance(v, float):
        return 'float `%s`' % v
    if isinstance(v, list):
        return 'sequence'
    if isinstance(v, dict):
        return 'map'
    return 'value'

def _parse_toml_value(s, pos):
    # pos index into s; return (value, newpos).  Raises TomlError with rough msg.
    while pos < len(s) and s[pos] in ' \t':
        pos += 1
    if pos >= len(s):
        raise TomlError('empty')
    c = s[pos]
    if c == '"':
        # basic string, handle triple
        if s.startswith('"""', pos):
            end = s.find('"""', pos + 3)
            if end == -1:
                raise TomlError('unterminated')
            return s[pos + 3:end], end + 3
        out = []
        i = pos + 1
        while i < len(s):
            ch = s[i]
            if ch == '"':
                return ''.join(out), i + 1
            if ch == '\\' and i + 1 < len(s):
                esc = s[i + 1]
                mp = {'n': '\n', 't': '\t', 'r': '\r', '"': '"', '\\': '\\', 'b': '\b', 'f': '\f', '/': '/'}
                if esc in mp:
                    out.append(mp[esc]); i += 2; continue
                if esc == 'u' and i + 5 < len(s) + 1:
                    try:
                        out.append(chr(int(s[i + 2:i + 6], 16))); i += 6; continue
                    except Exception:
                        pass
                out.append(esc); i += 2; continue
            out.append(ch); i += 1
        raise TomlError('unterminated')
    if c == "'":
        if s.startswith("'''", pos):
            end = s.find("'''", pos + 3)
            if end == -1:
                raise TomlError('unterminated')
            return s[pos + 3:end], end + 3
        end = s.find("'", pos + 1)
        if end == -1:
            raise TomlError('unterminated')
        return s[pos + 1:end], end + 1
    if c == '[':
        # array (single line only, enough)
        end = s.find(']', pos)
        if end == -1:
            raise TomlError('unterminated array')
        inner = s[pos + 1:end].strip()
        vals = []
        if inner:
            # naive split respecting strings
            parts = []
            depth = 0; in_str = None; cur = ''
            k = 0
            while k < len(inner):
                ch = inner[k]
                if in_str:
                    cur += ch
                    if ch == in_str:
                        in_str = None
                elif ch in '"\'':
                    in_str = ch; cur += ch
                elif ch == '[':
                    depth += 1; cur += ch
                elif ch == ']':
                    depth -= 1; cur += ch
                elif ch == ',' and depth == 0:
                    parts.append(cur); cur = ''
                else:
                    cur += ch
                k += 1
            if cur.strip():
                parts.append(cur)
            for p in parts:
                v, _ = _parse_toml_value(p.strip(), 0)
                vals.append(v)
        return vals, end + 1
    if c == '{':
        end = s.find('}', pos)
        if end == -1:
            raise TomlError('unterminated table')
        return {}, end + 1
    # bare token
    m = re.match(r'[^\s,\]#]+', s[pos:])
    if not m:
        raise TomlError('bad value')
    tok = m.group(0)
    endpos = pos + len(tok)
    if tok == 'true': return True, endpos
    if tok == 'false': return False, endpos
    # datetime / numbers kept as string marker
    try:
        return int(tok.replace('_', ''), 10), endpos
    except Exception:
        pass
    try:
        return float(tok.replace('_', '')), endpos
    except Exception:
        pass
    return ('__bare__', tok), endpos

def parse_handlr_toml(text):
    """Return dict of top-level keys. Raises TomlError(debug_text_for_panic)."""
    root = {}
    current = root
    seen_keys = set()
    lines = text.split('\n')
    offset = 0  # byte offset of line start in text (approx, chars)
    for lineno, raw_line in enumerate(lines):
        line = raw_line
        # strip comment outside strings
        stripped = line.strip()
        line_start_offset = offset
        offset += len(raw_line) + 1
        if not stripped:
            continue
        if stripped.startswith('#'):
            continue
        if stripped.startswith('['):
            if stripped.startswith('[['):
                current = {}
                continue
            if not stripped.endswith(']'):
                raise TomlError(_bad_toml_debug('Wanted { expected: "a right bracket", found: "a newline" }', lineno, len(line), line_start_offset + len(line)))
            sect = stripped[1:-1].strip()
            current = {}
            # store under a key that won't collide with flat keys
            root['__section__' + sect] = current
            continue
        # key = value
        # find '=' outside quotes
        eq = -1; in_str = None
        for idx, ch in enumerate(line):
            if in_str:
                if ch == in_str and (idx == 0 or line[idx - 1] != '\\'):
                    in_str = None
            elif ch in '"\'':
                in_str = ch
            elif ch == '=':
                eq = idx; break
            elif ch == '#':
                break
        if eq == -1:
            # mimic toml crate: wanted an equals
            # find first unexpected char similar to original for simple cases
            first_word_end = len(line)
            raise TomlError(_bad_toml_debug('Wanted { expected: "an equals", found: "an identifier" }', lineno, min(8, len(line)), line_start_offset + min(8, len(line))))
        key = line[:eq].strip().strip('"').strip("'")
        if not key:
            raise TomlError(_bad_toml_debug('Wanted { expected: "a key", found: "an equals" }', lineno, eq, line_start_offset + eq))
        val_str = line[eq + 1:]
        # strip comment outside string later; _parse accepts trailing
        try:
            val, vpos = _parse_toml_value(val_str, 0)
        except TomlError:
            # unexpected char errors for simple things: 'bad !'
            raise
        if isinstance(val, tuple) and val and val[0] == '__bare__':
            # invalid bare value like an identifier
            tok = val[1]
            # position of token
            col = eq + 1 + (len(val_str) - len(val_str.lstrip()))
            raise TomlError(_bad_toml_debug("Unexpected('%s')" % tok[0] if tok else 'Custom', lineno, col, line_start_offset + col))
        # duplicate key check within current table
        marker = (id(current), key)
        if marker in seen_keys:
            raise TomlError(_bad_toml_debug('Custom', lineno, eq, line_start_offset + eq, message='duplicate key: `%s`' % key))
        seen_keys.add(marker)
        current[key] = (val, val_str, eq, line_start_offset, lineno)
    return root

def _bad_toml_debug(kind, line, col, at, message=''):
    return 'Error { inner: ErrorInner { kind: %s, line: Some(%d), col: %d, at: Some(%d), message: "%s", key: [] } }' % (kind, line, col, at, message)

def load_config():
    cfg = ConfigObj()
    cfgdir = config_dir_path()
    cfg.cfg_dir = cfgdir
    if cfgdir is None:
        return cfg
    cfg.mimeapps_path = os.path.join(cfgdir, 'mimeapps.list')
    handlr_dir = os.path.join(cfgdir, 'handlr')
    toml_path = os.path.join(handlr_dir, 'handlr.toml')
    # create handlr dir
    if os.path.isdir(handlr_dir):
        pass
    elif os.path.lexists(handlr_dir):
        # exists as a file: falling through will fail on toml creation (ENOTDIR)
        pass
    else:
        try:
            os.makedirs(handlr_dir, exist_ok=True)
        except OSError as e:
            if e.errno == 20:  # NotADirectory
                panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: GeneralLoadError(%s)" % os_debug_exc(e))
            else:
                panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: DirectoryCreationFailed(%s)" % os_debug_exc(e))
    # toml file
    if os.path.isdir(toml_path):
        panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: ReadConfigurationFileError(%s)" % os_debug_from_errno(21))
    if not os.path.exists(toml_path):
        try:
            with open(toml_path, 'w', encoding='utf-8', newline='\n') as f:
                f.write(DEFAULT_CONFIG_TEXT)
        except OSError as e:
            panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: GeneralLoadError(%s)" % os_debug_exc(e))
    # read it
    try:
        with open(toml_path, 'rb') as f:
            data = f.read()
    except OSError as e:
        if e.errno == 21:
            panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: ReadConfigurationFileError(%s)" % os_debug_exc(e))
        panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: GeneralLoadError(%s)" % os_debug_exc(e))
    try:
        text = data.decode('utf-8')
    except Exception:
        panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: BadTomlData(%s)" % _bad_toml_debug('Custom', 0, 0, 0, 'invalid utf-8'))
    try:
        root = parse_handlr_toml(text)
    except TomlError as te:
        panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: BadTomlData(%s)" % te.debug_text)
    # extract fields
    for key, expected in (('enable_selector', 'bool'), ('selector', 'str')):
        if key in root and not isinstance(root[key], dict):
            val, val_str, eq, line_off, lineno = root[key]
            if expected == 'bool' and not isinstance(val, bool):
                col = eq + 1 + (len(val_str) - len(val_str.lstrip()))
                msg = 'invalid type: %s, expected a boolean' % _toml_type_name(val)
                dbg = 'Error { inner: ErrorInner { kind: Custom, line: Some(%d), col: %d, at: Some(%d), message: "%s", key: ["%s"] } }' % (lineno, col, line_off + col, msg, key)
                panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: BadTomlData(%s)" % dbg)
            if expected == 'str' and not isinstance(val, str):
                col = eq + 1 + (len(val_str) - len(val_str.lstrip()))
                msg = 'invalid type: %s, expected a string' % _toml_type_name(val)
                dbg = 'Error { inner: ErrorInner { kind: Custom, line: Some(%d), col: %d, at: Some(%d), message: "%s", key: ["%s"] } }' % (lineno, col, line_off + col, msg, key)
                panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: BadTomlData(%s)" % dbg)
            if key == 'enable_selector':
                cfg.enable_selector = bool(val)
            else:
                cfg.selector = val
    return cfg

def config_select(cfg, names):
    tokens = tokenize_exec(cfg.selector, panic_site=PANIC_CONFIG_UNWRAP)
    if not tokens:
        panic(PANIC_CONFIG_REMOVE[0], PANIC_CONFIG_REMOVE[1])
    binary = tokens[0]
    rest = tokens[1:]
    try:
        proc = subprocess.Popen([binary] + rest, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=None)
    except OSError:
        return None
    input_data = '\n'.join(names).encode('utf-8')
    try:
        out, _ = proc.communicate(input=input_data)
    except Exception:
        try:
            out = proc.stdout.read() if proc.stdout else b''
        except Exception:
            out = b''
    if out is None:
        out = b''
    selected = out.decode('utf-8', 'replace')
    # trim_end (Rust trim_end trims whitespace incl unicode)
    selected = re.sub(r'\s+$', '', selected, flags=re.UNICODE)
    if selected == '':
        return None
    return selected

# ---------------------------------------------------------------------------
# MimeApps (user) and System apps

class Apps:
    def __init__(self, cfg):
        self.cfg = cfg
        self.defaults = {}
        self.added = {}
        self.system = {}
        self._load_system()
        self._load_user()

    # -------- system --------
    def _load_system(self):
        seen = set()
        for app_dir in application_dirs():
            try:
                entries = list(os.scandir(app_dir))
            except OSError:
                continue
            for entry in entries:
                name = entry.name
                if name in seen:
                    continue
                if not name.endswith('.desktop'):
                    continue
                seen.add(name)
                path = os.path.join(app_dir, name)
                de = parse_desktop_file(path)
                if de is None:
                    continue
                for mk in de.mime_types:
                    self.system.setdefault(mk, []).append(name)

    # -------- user --------
    def _user_panic_io(self, e):
        panic("src/apps/user.rs:12:65", "called `Result::unwrap()` on an `Err` value: Io(%s)" % os_debug_exc(e))

    def _load_user(self):
        cfg = self.cfg
        if cfg.mimeapps_path is None:
            return
        path = cfg.mimeapps_path
        # open read/write, create if missing (like OpenOptions)
        try:
            fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o644)
        except OSError as e:
            self._user_panic_io(e)
        try:
            data = b''
            while True:
                chunk = os.read(fd, 65536)
                if not chunk:
                    break
                data += chunk
        except OSError as e:
            try: os.close(fd)
            except Exception: pass
            self._user_panic_io(e)
        try:
            os.close(fd)
        except Exception:
            pass
        try:
            text = data.decode('utf-8')
        except Exception:
            panic("src/apps/user.rs:12:65", 'called `Result::unwrap()` on an `Err` value: Io(Custom { kind: InvalidData, error: "stream did not contain valid UTF-8" })')
        defaults, added = parse_mimeapps_text(text, self)
        self.defaults = defaults
        self.added = added

    def save_user(self):
        cfg = self.cfg
        if cfg.mimeapps_path is None:
            io_not_found()
        out = self._serialize_user()
        try:
            with open(cfg.mimeapps_path, 'wb') as f:
                f.write(out.encode('utf-8'))
        except OSError as e:
            raise MainError('Io(%s)' % os_debug_exc(e))

    def _serialize_user(self):
        parts = ['[Added Associations]\n']
        for mk in sorted(self.added.keys(), key=lambda m: m.canonical()):
            parts.append('%s=%s;\n' % (mk.essence(), ';'.join(self.added[mk])))
        parts.append('\n[Default Applications]\n')
        for mk in sorted(self.defaults.keys(), key=lambda m: m.canonical()):
            parts.append('%s=%s;\n' % (mk.essence(), ';'.join(self.defaults[mk])))
        return ''.join(parts)

    # -------- handler resolution --------
    def _find_handlers_names(self, handler_tokens):
        # returns list of (token, name) for tokens that resolve
        res = []
        for tok in handler_tokens:
            cand, entry = lookup_desktop(tok)
            if entry is not None:
                res.append((tok, entry.name))
            else:
                res.append((tok, tok))
        return res

    def resolve_handler_token(self, mime):
        """Return handler token (desktop file name) or None following get logic."""
        cfg = self.cfg
        # A. defaults exact or wildcard
        lst = None
        if mime in self.defaults:
            lst = self.defaults[mime]
        else:
            wild, _ = parse_mime_str('%s/*' % mime.typ)
            if wild in self.defaults:
                lst = self.defaults[wild]
        if lst:
            if cfg.enable_selector and len(lst) > 1:
                named = []
                for tok in lst:
                    cand, entry = lookup_desktop(tok)
                    named.append(entry.name if entry is not None else tok)
                sel = config_select(cfg, named)
                if sel is None:
                    return lst[0]
                # find by name
                for tok, nm in zip(lst, named):
                    if nm == sel:
                        return tok
                panic("src/apps/user.rs:67:26", "called `Option::unwrap()` on a `None` value")
            return lst[0]
        # B. added exact
        if mime in self.added and self.added[mime]:
            return self.added[mime][0]
        # C. system exact
        if mime in self.system and self.system[mime]:
            return self.system[mime][0]
        return None

    def full_handler(self, mime, args):
        """Return (token, name, cmd_string, command_tokens) or raise MainError.
        command_tokens is the full token list including binary."""
        token = self.resolve_handler_token(mime)
        if token is None:
            io_not_found()
        cand, entry = lookup_desktop(token)
        if entry is None:
            io_not_found()
        tokens = self._entry_command_tokens(entry, args)
        return token, entry.name, tokens

    def _entry_command_tokens(self, entry, args):
        if entry.terminal:
            term_mime, _ = parse_mime_str('x-scheme-handler/terminal')
            term_token = self.resolve_handler_token(term_mime)
            if term_token is None:
                io_not_found()
            tcand, tentry = lookup_desktop(term_token)
            if tentry is None:
                io_not_found()
            term_tokens = tokenize_exec(tentry.exec)
            app_tokens = expand_exec_tokens(tokenize_exec(entry.exec), list(args))
            return term_tokens + ['-e'] + app_tokens
        else:
            return expand_exec_tokens(tokenize_exec(entry.exec), list(args))

    def get_cmd_string(self, mime):
        token, name, tokens = self.full_handler(mime, [])
        if not tokens:
            panic(PANIC_DESKTOP_REMOVE[0], PANIC_DESKTOP_REMOVE[1])
        binary = tokens[0]
        rest = tokens[1:]
        return token, name, '%s %s' % (binary, ' '.join(rest))

    def execute_handler(self, mime, args):
        token, name, tokens = self.full_handler(mime, list(args))
        if not tokens:
            panic(PANIC_DESKTOP_REMOVE[0], PANIC_DESKTOP_REMOVE[1])
        binary = tokens[0]
        rest = tokens[1:]
        spawn_detached(binary, rest)

_spawned = []

def spawn_detached(binary, rest):
    try:
        p = subprocess.Popen([binary] + list(rest), stdin=None, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, close_fds=True)
        _spawned.append(p)
    except OSError:
        io_not_found()
    except ValueError:
        io_not_found()

# -------- mimeapps grammar --------

def _is_name_char(ch):
    if ch in '$<>^`|~':
        return False
    if ch == '+':
        return True
    cat = unicodedata.category(ch)
    if cat[0] in ('L', 'M', 'N', 'P') or ch == ' ':
        return True
    return False

def _is_section_char(ch):
    cat = unicodedata.category(ch)
    if cat[0] in ('L', 'M', 'N') or ch in (' ', '-', '_', '='):
        return True
    return False

def _is_value_char(ch):
    cat = unicodedata.category(ch)
    if cat[0] == 'C':
        return False
    return True

class MimeappsParseFailure(Exception):
    def __init__(self, byte_pos, line_no, col_no, line_text, has_newline, positives):
        self.byte_pos = byte_pos
        self.line_no = line_no
        self.col_no = col_no
        self.line_text = line_text
        self.has_newline = has_newline
        self.positives = positives

def _pest_line_repr(line_text, has_newline):
    inner = ''
    for ch in line_text:
        o = ord(ch)
        if ch == '"': inner += '\\"'
        elif ch == '\\': inner += '\\\\'
        elif ch == '\t': inner += '\\t'
        elif ch == '\r': inner += '\\r'
        elif o == 0: inner += '\\0'
        elif o < 0x20 or o == 0x7f: inner += '\\u{%x}' % o
        else: inner += ch
    if has_newline:
        inner += '\u240a'
    return '"%s"' % inner

def parse_mimeapps_text(text, apps):
    # returns (defaults, added)
    # enforce trailing newline
    physical = text.split('\n')
    # If text ends with \n, last split piece is '' sentinel
    ends_with_nl = text.endswith('\n') or text == ''
    lines = []
    if text == '':
        lines = []
    else:
        # physical lines without newline char; drop final sentinel if ends with nl
        raw_lines = physical[:-1] if ends_with_nl else physical
        for idx, rl in enumerate(raw_lines):
            has_nl = ends_with_nl or idx < len(raw_lines) - 1
            # Actually each line except possibly last has newline
            has_nl = True if idx < len(raw_lines) - 1 else ends_with_nl
            ln = rl[:-1] if rl.endswith('\r') else rl
            lines.append((ln, has_nl, rl))
    if text != '' and not ends_with_nl:
        # failure on last line
        ln, _, _ = lines[-1]
        # compute position
        byte_pos = len(text.encode('utf-8'))
        line_no = len(lines)
        col_no = len(ln) + 1
        if ln.startswith('#'):
            positives = ['name_char']
        elif ln.startswith('['):
            positives = ['section_char']
        elif '=' in ln:
            positives = ['value_char']
        elif ln == '':
            positives = ['value_char']
        else:
            positives = ['name_char']
        raise MimeappsParseFailure(byte_pos, line_no, col_no, ln, False, positives)
    defaults = {}
    added = {}
    removed = {}
    current_name = None
    # byte offsets per line
    offset = 0
    for (ln, has_nl, raw_with_cr) in lines:
        line_bytes_len = len((raw_with_cr + '\n').encode('utf-8')) if has_nl else len(raw_with_cr.encode('utf-8'))
        line_start = offset
        offset += line_bytes_len
        if ln == '':
            continue
        if ln.startswith('#'):
            for j, ch in enumerate(ln[1:]):
                if not _is_name_char(ch):
                    byte_pos = line_start + len(ln[:1 + j].encode('utf-8'))
                    raise MimeappsParseFailure(byte_pos, lines.index((ln, has_nl, raw_with_cr)) + 1 if False else 0, 0, ln, has_nl, ['name_char'])
            continue
        if ln.startswith('['):
            # section
            if not ln.endswith(']') or len(ln) < 3:
                # location at first ']' if any else at end
                if ']' in ln:
                    pos_chars = ln.index(']')
                    byte_pos = line_start + len(ln[:pos_chars].encode('utf-8'))
                    col = pos_chars + 1
                else:
                    byte_pos = line_start + len(ln.encode('utf-8'))
                    col = len(ln) + 1
                # line number computed below generically - we recompute in handler
                fail = MimeappsParseFailure(byte_pos, 0, col, ln, has_nl, ['section_char'])
                fail._line_no_raw = None
                raise fail
            inner = ln[1:-1]
            if inner == '':
                byte_pos = line_start + 1
                fail = MimeappsParseFailure(byte_pos, 0, 2, ln, has_nl, ['name_char'])
                raise fail
            bad = None
            for j, ch in enumerate(inner):
                if not _is_section_char(ch):
                    bad = j; break
            if bad is not None:
                if ']' in ln:
                    pos_chars = ln.index(']')
                    byte_pos = line_start + len(ln[:pos_chars].encode('utf-8'))
                    col = pos_chars + 1
                else:
                    byte_pos = line_start + len(ln.encode('utf-8')); col = len(ln) + 1
                raise MimeappsParseFailure(byte_pos, 0, col, ln, has_nl, ['section_char'])
            current_name = inner
            continue
        # entry line
        if ln[0] == '\t' or ln[0] == '\x00':
            raise MimeappsParseFailure(line_start, 0, 1, ln, has_nl, ['EOI', 'name_char', 'section', 'comment'])
        eq = ln.find('=')
        if eq == -1:
            byte_pos = line_start + len(ln.encode('utf-8'))
            raise MimeappsParseFailure(byte_pos, 0, len(ln) + 1, ln, has_nl, ['name_char'])
        if eq == 0:
            raise MimeappsParseFailure(line_start, 0, 1, ln, has_nl, ['EOI', 'name_char', 'section', 'comment'])
        name = ln[:eq]
        value = ln[eq + 1:]
        for j, ch in enumerate(name):
            if not _is_name_char(ch):
                byte_pos = line_start + len(ln[:j].encode('utf-8'))
                raise MimeappsParseFailure(byte_pos, 0, j + 1, ln, has_nl, ['name_char'])
        if value == '':
            byte_pos = line_start + len(ln.encode('utf-8'))
            raise MimeappsParseFailure(byte_pos, 0, len(ln) + 1, ln, has_nl, ['value_char'])
        for j, ch in enumerate(value):
            if not _is_value_char(ch):
                byte_pos = line_start + len((ln[:eq + 1 + j]).encode('utf-8'))
                raise MimeappsParseFailure(byte_pos, 0, eq + 2 + j, ln, has_nl, ['value_char'])
        # record entry
        target = None
        if current_name == 'Default Applications':
            target = defaults
        elif current_name == 'Added Associations':
            target = added
        elif current_name == 'Removed Associations':
            target = removed
        else:
            target = None
        if target is not None:
            mk, err = parse_mime_str(name)
            if mk is None:
                continue
            tokens = value.split(';')
            uniq = []
            for t in tokens:
                if t not in uniq:
                    uniq.append(t)
            filtered = []
            for t in uniq:
                cand, entry = lookup_desktop(t)
                if entry is not None:
                    filtered.append(t)
            if filtered:
                target[mk] = filtered
            else:
                if mk in target:
                    del target[mk]
    return defaults, added

def mimeapps_panic_from_failure(text, fail):
    # recompute line number / col if needed
    # find line by searching physical lines
    phys = text.split('\n')
    # Determine line containing byte_pos roughly by iterating
    # Simpler: we stored col=0 etc for some; recompute from byte_pos
    data = text.encode('utf-8')
    upto = data[:fail.byte_pos]
    try:
        upto_text = upto.decode('utf-8')
    except Exception:
        upto_text = upto.decode('utf-8', 'replace')
    line_no = upto_text.count('\n') + 1
    last_nl = upto_text.rfind('\n')
    if last_nl == -1:
        col_no = len(upto_text) + 1
        line_text = phys[0] if phys else ''
    else:
        col_no = len(upto_text) - last_nl
        # line text is the physical line at line_no
        idx = line_no - 1
        line_text = phys[idx] if idx < len(phys) else ''
    if fail.col_no:
        col_no = fail.col_no
    # line_text from stored if available
    if fail.line_text:
        line_text = fail.line_text
    has_nl = True
    # Determine if that line had newline in source
    # If byte position points at newline char, line is terminated.
    positives_str = ', '.join(fail.positives)
    line_repr = _pest_line_repr(line_text, has_nl and not (text != '' and not text.endswith('\n') and line_no == len(phys)))
    # For no-trailing-newline case, line repr without symbol
    if text != '' and not text.endswith('\n'):
        # check whether the failing line is last line
        if line_no == len(phys):
            line_repr = _pest_line_repr(line_text, False)
    err = 'Error { variant: ParsingError { positives: [%s], negatives: [] }, location: Pos(%d), line_col: Pos((%d, %d)), path: None, line: %s, continued_line: None }' % (positives_str, fail.byte_pos, line_no, col_no, line_repr)
    panic("src/apps/user.rs:12:65", "called `Result::unwrap()` on an `Err` value: ParseApps(%s)" % err)

# wrap parse to panic
orig_parse_mimeapps_text = parse_mimeapps_text
def parse_mimeapps_text_panic(text, apps):
    try:
        return orig_parse_mimeapps_text(text, apps)
    except MimeappsParseFailure as f:
        mimeapps_panic_from_failure(text, f)
# monkey patch reference used in Apps
parse_mimeapps_text = parse_mimeapps_text_panic

# ---------------------------------------------------------------------------
# URL handling

SPECIAL_SCHEMES = {'http': 80, 'https': 443, 'ws': 80, 'wss': 443, 'ftp': 21, 'file': None}

def _pct_encode(s, encode_set, preserve_pct=True):
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        if preserve_pct and ch == '%':
            out.append('%'); i += 1; continue
        o = ord(ch)
        if o < 0x20 or o == 0x7f or o > 0x7e or ch in encode_set:
            for b in ch.encode('utf-8'):
                out.append('%%%02X' % b)
        else:
            out.append(ch)
        i += 1
    return ''.join(out)

def _encode_path_segment(seg):
    return _pct_encode(seg, set(' "<>?#'))

def _encode_query(q):
    return _pct_encode(q, set(' "#'))

def _encode_fragment(f):
    return _pct_encode(f, set(' "<>`'))

def _encode_userinfo(u):
    return _pct_encode(u, set(' /?:@[]'))

def _ipv4_canonical(host):
    parts = host.split('.')
    if len(parts) > 4:
        return None
    nums = []
    for p in parts:
        if p == '':
            return None
        try:
            if p.lower().startswith('0x'):
                v = int(p, 16)
            elif len(p) > 1 and p[0] == '0' and p.isdigit():
                v = int(p, 8)
            elif p.isdigit():
                v = int(p, 10)
            else:
                return None
        except Exception:
            return None
        nums.append(v)
    # validate
    for v in nums[:-1]:
        if v > 255:
            return None
    last_max = 256 ** (5 - len(nums))
    if nums[-1] >= last_max:
        return None
    addr = 0
    for idx, v in enumerate(nums[:-1]):
        addr += v * (256 ** (3 - idx))
    addr += nums[-1]
    return str(ipaddress.IPv4Address(addr))

def _host_serialize(host, special):
    if host == '':
        return None
    if host.startswith('['):
        # ipv6
        end = host.find(']')
        if end == -1:
            return None
        inside = host[1:end]
        try:
            ip = ipaddress.IPv6Address(inside)
            return '[' + ip.compressed + ']', host[end + 1:]
        except Exception:
            return None
    # split host/port is done by caller for authority case
    h = host
    if special:
        # percent or spaces invalid
        if any(ord(c) <= 0x20 or ord(c) == 0x7f for c in h):
            return None
        hl = h.lower()
        # ipv4 attempt: if last part numeric-ish
        parts = hl.split('.')
        last = parts[-1] if parts else ''
        numeric_last = False
        if last:
            if last.isdigit() or last.lower().startswith('0x'):
                numeric_last = True
        if numeric_last:
            canon = _ipv4_canonical(hl)
            if canon is not None:
                return canon
            # else fall through as domain
        # IDNA
        labels = hl.split('.')
        out_labels = []
        for lab in labels:
            if lab == '':
                out_labels.append('')
                continue
            if all(ord(c) < 128 for c in lab):
                out_labels.append(lab)
            else:
                try:
                    enc = lab.encode('idna').decode('ascii')
                    out_labels.append(enc)
                except Exception:
                    try:
                        enc = lab.encode('punycode').decode('ascii')
                        out_labels.append('xn--' + enc)
                    except Exception:
                        out_labels.append(lab)
        return '.'.join(out_labels)
    else:
        return h

class ParsedUrl:
    def __init__(self):
        self.scheme = ''
        self.is_special = False
        self.has_authority = False
        self.username = ''
        self.password = None
        self.host = None
        self.host_raw = None
        self.port = None
        self.path_segments = []  # encoded segments, path starts with / if non-empty for authority
        self.path_str = ''  # serialized path
        self.query = None
        self.fragment = None
        self.opaque_path = None
        self.file_host_bad = False
        self.file_path_str = None
        self.file_path_display = '/'
        self.file_invalid_utf8 = False

def _split_authority(rest_after_slashes):
    # returns (authority, remainder starting with delimiter or '')
    idx = len(rest_after_slashes)
    for delim in ('/', '\\', '?', '#'):
        j = rest_after_slashes.find(delim)
        if j != -1 and j < idx:
            idx = j
    return rest_after_slashes[:idx], rest_after_slashes[idx:]

def _parse_authority(auth, special):
    # returns (username,password,host_serialized,port) or None
    username = ''
    password = None
    hostport = auth
    if '@' in auth:
        userinfo, hostport = auth.rsplit('@', 1)
        if ':' in userinfo:
            username, password = userinfo.split(':', 1)
        else:
            username = userinfo
        username = _encode_userinfo(username)
        if password is not None:
            password = _pct_encode(password, set(' /?:@[]'))
    host = hostport
    port = None
    if hostport.startswith('['):
        end = hostport.find(']')
        if end == -1:
            return None
        host = hostport[:end + 1]
        restp = hostport[end + 1:]
        if restp:
            if not restp.startswith(':'):
                return None
            pstr = restp[1:]
            if pstr == '':
                port = None
            elif not pstr.isdigit():
                return None
            else:
                port = int(pstr)
                if port > 65535:
                    return None
        hs = _host_serialize(host, special)
        if hs is None:
            return None
        host_s = hs[0] if isinstance(hs, tuple) else hs
        return username, password, host_s, port
    else:
        if ':' in hostport:
            # last colon
            hpart, pstr = hostport.rsplit(':', 1)
            if ':' in hpart:
                return None
            host = hpart
            if pstr == '':
                port = None
            elif not pstr.isdigit():
                return None
            else:
                port = int(pstr)
                if port > 65535:
                    return None
        if host == '':
            return None
        hs = _host_serialize(host, special)
        if hs is None:
            return None
        host_s = hs[0] if isinstance(hs, tuple) else hs
        return username, password, host_s, port

def _normalize_path_segments(path_raw, special):
    # path_raw starts maybe; returns list of encoded segments (without leading slash), trailing_slash flag
    # Split on / (and \ if special)
    if special:
        parts = re.split(r'[/\\]', path_raw)
    else:
        parts = path_raw.split('/')
    # path_raw expected to start with '/', first part ''
    segments = []
    trailing = False
    # We'll process parts after handling leading slash in caller
    for idx, part in enumerate(parts):
        is_last = idx == len(parts) - 1
        low = part.lower()
        if low in ('.', '%2e'):
            if is_last:
                trailing = True
            continue
        if low in ('..', '.%2e', '%2e.', '%2e%2e'):
            if segments:
                segments.pop()
            if is_last:
                trailing = True
            continue
        segments.append(_encode_path_segment(part))
        trailing = False
    if path_raw.endswith('/') or path_raw.endswith('\\') and special:
        trailing = True
    return segments, trailing

def parse_url(raw):
    s = raw.replace('\t', '').replace('\n', '').replace('\r', '')
    s = s.strip(''.join(chr(i) for i in range(0x21)))
    m = re.match(r'^([A-Za-z][A-Za-z0-9+.\-]*):(.*)$', s, re.DOTALL)
    if not m:
        return None
    scheme = m.group(1).lower()
    rest = m.group(2)
    url = ParsedUrl()
    url.scheme = scheme
    special = scheme in SPECIAL_SCHEMES
    url.is_special = special
    # split fragment / query for path handling later, but keep delimiters in rest parsing
    if scheme == 'file':
        return _parse_file_url(url, rest)
    if special:
        # strip leading slashes/backslashes
        stripped = rest.lstrip('/\\')
        if stripped == '':
            return None
        auth, remainder = _split_authority(stripped)
        if auth == '':
            return None
        parsed = _parse_authority(auth, True)
        if parsed is None:
            return None
        username, password, host_s, port = parsed
        if port is not None and SPECIAL_SCHEMES.get(scheme) == port:
            port = None
        url.username = username; url.password = password; url.host = host_s; url.port = port; url.has_authority = True
        # remainder is path/query/fragment
        pqf = remainder
        # split fragment
        frag = None; query = None
        if '#' in pqf:
            pqf, frag = pqf.split('#', 1)
        if '?' in pqf:
            pqf, q = pqf.split('?', 1)
            query = q
        if pqf == '':
            segs = []; trailing = True
            path_str = '/'
        else:
            segs, trailing = _normalize_path_segments(pqf, True)
            path_str = '/' + '/'.join(segs)
            if trailing and not path_str.endswith('/'):
                path_str += '/'
            if segs and pqf == '':
                path_str = '/'
        url.path_str = path_str
        url.query = _encode_query(query) if query is not None else None
        url.fragment = _encode_fragment(frag) if frag is not None else None
        return url
    else:
        # non-special
        frag = None; query = None
        main = rest
        if '#' in main:
            main, frag = main.split('#', 1)
        if '?' in main:
            main, q = main.split('?', 1)
            query = q
        if main.startswith('//'):
            after = main[2:]
            # authority until slash
            idx = after.find('/')
            if idx == -1:
                auth = after; path_raw = ''
            else:
                auth = after[:idx]; path_raw = after[idx:]
            if auth == '':
                # treat whole main as opaque-ish path
                url.has_authority = False
                url.opaque_path = main
                url.path_str = main
            else:
                parsed = _parse_authority(auth, False)
                if parsed is None:
                    return None
                username, password, host_s, port = parsed
                url.username = username; url.password = password; url.host = host_s; url.port = port; url.has_authority = True
                if path_raw == '':
                    url.path_str = ''
                else:
                    segs, trailing = _normalize_path_segments(path_raw, False)
                    path_str = '/' + '/'.join(segs)
                    if trailing and not path_str.endswith('/'):
                        path_str += '/'
                    url.path_str = path_str
        else:
            url.has_authority = False
            # opaque path: encode non-ascii / controls only, preserve spaces
            url.opaque_path = _pct_encode(main, set(), preserve_pct=True) if False else _encode_opaque(main)
            url.path_str = url.opaque_path
        url.query = _encode_query(query) if query is not None else None
        url.fragment = _encode_fragment(frag) if frag is not None else None
        return url

def _encode_opaque(s):
    out = []
    for ch in s:
        o = ord(ch)
        if o < 0x20 or o == 0x7f or o > 0x7e:
            for b in ch.encode('utf-8'):
                out.append('%%%02X' % b)
        else:
            out.append(ch)
    return ''.join(out)

def _parse_file_url(url, rest):
    url.is_special = True
    url.has_authority = True
    main = rest
    frag = None; query = None
    if '#' in main:
        main, frag = main.split('#', 1)
    if '?' in main:
        main, q = main.split('?', 1)
        query = q
    host = ''
    path_raw = main
    if main.startswith('//'):
        after = main[2:]
        # authority until / or backslash
        idx = len(after)
        for delim in ('/', '\\'):
            j = after.find(delim)
            if j != -1 and j < idx:
                idx = j
        host = after[:idx]
        path_raw = after[idx:] if idx < len(after) else ''
    elif main.startswith('/') or main == '':
        host = ''
        path_raw = main
    else:
        # file:relative  -> path is relative name, will be rooted
        host = ''
        path_raw = main
    host_low = host.lower()
    # normalize path segments encoded
    if path_raw == '':
        segs_enc = []
        trailing = True
    else:
        pr = path_raw if path_raw.startswith('/') else '/' + path_raw
        segs_enc, trailing = _normalize_path_segments(pr, True)
    display_path = '/' + '/'.join(segs_enc)
    if (trailing or not segs_enc) and not display_path.endswith('/'):
        # For file path, if original ended without slash, don't force unless empty
        if not segs_enc:
            display_path = '/'
    url.file_path_display = display_path if display_path else '/'
    # drive letter check
    drive = False
    if segs_enc:
        first = segs_enc[0]
        if re.match(r'^[A-Za-z]:$', first) or re.match(r'^[A-Za-z]\|$', first):
            drive = True
    if host_low not in ('', 'localhost') and not drive:
        url.file_host_bad = True
    # decode segments to path string
    decoded_segments = []
    invalid = False
    for seg in segs_enc:
        # percent decode
        bs = bytearray()
        i = 0
        while i < len(seg):
            if seg[i] == '%' and i + 2 < len(seg) and all(c in '0123456789abcdefABCDEF' for c in seg[i + 1:i + 3]):
                bs.append(int(seg[i + 1:i + 3], 16)); i += 3
            else:
                bs.extend(seg[i].encode('utf-8')); i += 1
        try:
            dec = bytes(bs).decode('utf-8')
        except Exception:
            invalid = True
            dec = bytes(bs).decode('utf-8', 'replace')
        decoded_segments.append(dec)
    url.file_invalid_utf8 = invalid
    fpath = '/' + '/'.join(decoded_segments)
    if trailing and decoded_segments and not fpath.endswith('/'):
        # preserve trailing slash if original path_raw ended with slash (decoded path will be checked is_dir anyway)
        if path_raw.endswith('/') or path_raw.endswith('\\'):
            fpath += '/'
    if not decoded_segments:
        fpath = '/'
    url.file_path_str = fpath
    url.path_str = display_path
    url.query = query
    url.fragment = frag
    return url

def url_serialize(url):
    if url.scheme == 'file':
        return url.file_path_str or '/'
    parts = [url.scheme, ':']
    if url.has_authority:
        parts.append('//')
        if url.username:
            parts.append(url.username)
            if url.password is not None:
                parts.append(':' + url.password)
            parts.append('@')
        elif url.password is not None:
            # username empty but password present: original keeps :pass@
            parts.append(':' + url.password + '@')
        if url.host:
            parts.append(url.host)
        if url.port is not None:
            parts.append(':%d' % url.port)
        parts.append(url.path_str)
    else:
        parts.append(url.path_str)
    if url.query is not None:
        parts.append('?' + url.query)
    if url.fragment is not None:
        parts.append('#' + url.fragment)
    return ''.join(parts)

