            # We approximate: if any sub token bytes are invalid utf-8 and appear after '--' or as a path,
            # original panics at retrieval time. To be safe, check all sub tokens that were
            # assigned as values: reconstruct by scanning sub_tokens_bytes against decoded values.
            for tb in sub_tokens_bytes:
                try:
                    tb.decode('utf-8')
                except Exception:
                    # only panic if this token was used as a positional value (not a flag name already handled)
                    txt = tb.decode('utf-8', 'replace')
                    if txt in values.get('paths', []):
                        panic("/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap-3.0.0-beta.2/src/parse/matches/arg_matches.rs:220:28", "unexpected invalid UTF-8 code point")
        if sub == 'launch':
            for tb in sub_tokens_bytes:
                try:
                    tb.decode('utf-8')
                except Exception:
                    txt = tb.decode('utf-8', 'replace')
                    if txt in values.get('args', []):
                        panic("/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap-3.0.0-beta.2/src/parse/matches/arg_matches.rs:220:28", "unexpected invalid UTF-8 code point")

