                sys.stdout.write(''.join(out))
            else:
                sys.stdout.write(format_table(map_to_rows(apps.defaults)))
            return 0
        elif sub == 'get':
            mime = mime_from_validated(values['mime'][0])
            if mime is None:
                io_not_found()
            if flags_seen.get('json'):
                token, name, cmd = apps.get_cmd_string(mime)
                obj = {"handler": token, "name": name, "cmd": cmd}
                sys.stdout.write(json.dumps(obj, ensure_ascii=False, separators=(',', ':')) + "\n")
            else:
