            for p in paths:
                mk, arg_str, _ = classify_open_arg(p)
                if mk == '__invalid__':
                    io_not_found()
                if mk not in groups:
                    groups[mk] = []
                    group_order.append(mk)
                groups[mk].append(arg_str)
