    msg = os.strerror(err)
    kind_map = {
        1: "PermissionDenied", 2: "NotFound", 3: "NotFound", 4: "Interrupted",
        5: "Uncategorized", 6: "NotFound", 11: "WouldBlock", 13: "PermissionDenied",
        14: "BadAddress", 17: "AlreadyExists", 20: "NotADirectory", 21: "IsADirectory",
        22: "InvalidInput", 24: "Uncategorized", 28: "StorageFull", 32: "BrokenPipe",
        36: "InvalidFilename", 40: "FilesystemLoop", 61: "Uncategorized",
        110: "TimedOut", 111: "ConnectionRefused", 104: "ConnectionReset",
        98: "AddrInUse", 99: "AddrNotAvailable", 103: "ConnectionAborted",
        106: "AlreadyConnected", 107: "NotConnected",
    }
    kind = kind_map.get(err, "Uncategorized")
    return 'Os { code: %d, kind: %s, message: "%s" }' % (err, kind, msg)

def os_debug_exc(e):
    return os_debug_from_errno(e.errno if getattr(e, 'errno', None) is not None else 2)

class MainError(Exception):
    pass

def io_not_found():
    raise MainError('Io(Os { code: 2, kind: NotFound, message: "No such file or directory" })')

def rust_str_debug(s):
    out = []
    for ch in s:
        o = ord(ch)
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif o == 0: out.append('\\0')
        elif o < 0x20 or o == 0x7f: out.append('\\u{%x}' % o)
        else: out.append(ch)
    return '"' + ''.join(out) + '"'

# ---------------------------------------------------------------------------
# XDG / home

def home_dir():
    h = os.environ.get('HOME')
    if h:
        return h
    try:
        import pwd
        return pwd.getpwuid(os.getuid()).pw_dir
    except Exception:
        return None

def config_dir_path():
    x = os.environ.get('XDG_CONFIG_HOME')
    if x and os.path.isabs(x):
        return x
    h = home_dir()
    if h:
        return os.path.join(h, '.config')
    return None

def data_home_path():
    x = os.environ.get('XDG_DATA_HOME')
    if x and os.path.isabs(x):
        return x
    h = home_dir()
    if h:
        return os.path.join(h, '.local', 'share')
    return None

def data_dirs_list():
    raw = os.environ.get('XDG_DATA_DIRS')
    result = []
    if raw is not None:
        for part in raw.split(':'):
            if part and os.path.isabs(part):
                result.append(part)
        if result:
            return result
        return ['/usr/local/share', '/usr/share']
    return ['/usr/local/share', '/usr/share']

def application_dirs():
    dirs = []
    dh = data_home_path()
    if dh:
        dirs.append(os.path.join(dh, 'applications'))
    for d in data_dirs_list():
        dirs.append(os.path.join(d, 'applications'))
    return dirs

# ---------------------------------------------------------------------------
# Mime parsing (Rust `mime` crate behaviour)

TOKEN_CHARS = set(b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!#$%&'*+-.^_`|~")

class MimeKey:
    __slots__ = ('typ', 'sub', 'params')
    def __init__(self, typ, sub, params=()):
        self.typ = typ
        self.sub = sub
        self.params = tuple(params)
    def essence(self):
        return "%s/%s" % (self.typ, self.sub)
    def canonical(self):
        s = self.essence()
        for (k, v) in self.params:
            s += "; %s=%s" % (k, v)
        return s
    def __eq__(self, other):
        return isinstance(other, MimeKey) and self.typ == other.typ and self.sub == other.sub and self.params == other.params
    def __hash__(self):
        return hash((self.typ, self.sub, self.params))
    def __repr__(self):
        return 'MimeKey(%r)' % self.canonical()

def _mime_invalid(bts, pos):
    return "mime parse error: an invalid token was encountered, %X at position %d" % (bts[pos], pos)

def parse_mime_str(s):
    """Return (MimeKey or None, error string or None).
    If subtype is empty and string ends there, returns MimeKey with sub='' and
    error None (the validator turns this into `bad mime:`)."""
    try:
        bts = s.encode('utf-8')
    except Exception:
        bts = os.fsencode(s)
    n = len(bts)
    i = 0
    # type
    while i < n:
        b = bts[i]
        if b == 0x2f:  # /
            if i == 0:
                return None, _mime_invalid(bts, i)
            break
        if b not in TOKEN_CHARS:
            return None, _mime_invalid(bts, i)
        i += 1
    if i >= n:
        return None, "mime parse error: a slash (/) was missing between the type and subtype"
    typ = bts[:i].decode('ascii', 'replace').lower()
    sub_start = i + 1
    i = sub_start
    while i < n:
        b = bts[i]
        if b == 0x3b:  # ;
            break
        if b not in TOKEN_CHARS:
            return None, _mime_invalid(bts, i)
        i += 1
    sub = bts[sub_start:i].decode('ascii', 'replace').lower()
    if sub == '':
        if i < n:
            return None, _mime_invalid(bts, i)
        return MimeKey(typ, '', ()), None
    params = []
    # i at ';' or end
    while i < n:
        # bts[i] == ';'
        i += 1
        while i < n and bts[i] in (0x20, 0x09):
            i += 1
        if i >= n:
            break
        name_start = i
        while i < n:
            b = bts[i]
            if b == 0x3d:  # =
                break
            if b not in TOKEN_CHARS:
                return None, _mime_invalid(bts, i)
            i += 1
        if i >= n:
            return None, "mime parse error: an equals sign (=) was missing between a parameter and its value"
        if i == name_start:
            return None, _mime_invalid(bts, i)
        pname = bts[name_start:i].decode('ascii', 'replace').lower()
        i += 1  # =
        if i < n and bts[i] == 0x22:  # quote
            i += 1
            vstart = i
            # find closing quote
            j = bts.find(b'"', i)
            if j == -1 or j == vstart:
                return None, 'mime parse error: a quote (") was missing from a parameter value'
            pval = bts[vstart:j].decode('utf-8', 'replace')
            i = j + 1
            if i < n and bts[i] != 0x3b:
                return None, _mime_invalid(bts, i)
            params.append((pname, pval))
            # i at ; or end, loop continues
        else:
            vstart = i
            while i < n:
                b = bts[i]
                if b == 0x3b:
                    break
                if b not in TOKEN_CHARS:
                    return None, _mime_invalid(bts, i)
                i += 1
            pval = bts[vstart:i].decode('utf-8', 'replace')
            params.append((pname, pval))
    return MimeKey(typ, sub, tuple(params)), None

# ---------------------------------------------------------------------------
# shared-mime-info database (globs)

_glob_entries = None
_glob_aliases = None

def _mime_data_dirs():
    dirs = []
    dh = data_home_path()
    if dh:
        dirs.append(os.path.join(dh, 'mime'))
    for d in data_dirs_list():
        dirs.append(os.path.join(d, 'mime'))
    return dirs

def _glob_match(pattern, name):
    # translate glob to regex, * ? [seq]
    regex = ''
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '*':
            regex += '.*'
        elif c == '?':
            regex += '.'
        elif c == '[':
            j = pattern.find(']', i + 1)
            if j == -1:
                regex += re.escape(c)
            else:
                inner = pattern[i + 1:j]
                if inner.startswith('!'):
                    inner = '^' + inner[1:]
                regex += '[' + inner + ']'
                i = j
        else:
            regex += re.escape(c)
        i += 1
    return re.match('^' + regex + '$', name, re.DOTALL) is not None

def load_mime_globs():
    global _glob_entries, _glob_aliases
    if _glob_entries is not None:
        return _glob_entries, _glob_aliases
    entries = []  # (weight, pattern, mime_str)
    aliases = {}
    order = 0
    for mdir in _mime_data_dirs():
        # aliases
        try:
            with open(os.path.join(mdir, 'aliases'), 'r', encoding='utf-8', errors='replace') as f:
                for line in f:
                    parts = line.split()
                    if len(parts) >= 2:
                        aliases[parts[0]] = parts[1]
        except OSError:
            pass
        # globs2
        got_globs2 = False
        try:
            with open(os.path.join(mdir, 'globs2'), 'r', encoding='utf-8', errors='replace') as f:
                for line in f:
                    line = line.rstrip('\n')
                    if not line or line.startswith('#'):
                        continue
                    parts = line.split(':')
                    if len(parts) >= 3:
                        try:
                            w = int(parts[0])
                        except Exception:
                            w = 50
                        entries.append((w, parts[1], parts[2], order)); order += 1
                        got_globs2 = True
        except OSError:
            pass
        # globs (v1)
        try:
            with open(os.path.join(mdir, 'globs'), 'r', encoding='utf-8', errors='replace') as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith('#') or ':' not in line:
                        continue
                    mime, pattern = line.split(':', 1)
                    entries.append((50, pattern, mime, order)); order += 1
        except OSError:
            pass
        # packages xml
        pkgdir = os.path.join(mdir, 'packages')
        try:
            names = os.listdir(pkgdir)
        except OSError:
            names = []
        for name in names:
            if not name.endswith('.xml'):
                continue
            try:
                tree = ElementTree.parse(os.path.join(pkgdir, name))
            except Exception:
                continue
            for elem in tree.iter():
                tag = elem.tag
                if '}' in tag:
                    tag = tag.split('}', 1)[1]
                if tag != 'mime-type':
                    continue
                mtype = elem.get('type')
                if not mtype:
                    continue
                for child in elem:
                    ctag = child.tag
                    if '}' in ctag:
                        ctag = ctag.split('}', 1)[1]
                    if ctag == 'glob':
                        pattern = child.get('pattern')
                        if pattern:
                            try:
                                w = int(child.get('weight', '50'))
                            except Exception:
                                w = 50
                            entries.append((w, pattern, mtype, order)); order += 1
                    elif ctag == 'alias':
                        atype = child.get('type')
                        if atype:
                            aliases[atype] = mtype
    _glob_entries = entries
    _glob_aliases = aliases
    return entries, aliases

def guess_mime_by_filename(filename):
    if not filename:
        return None
    entries, aliases = load_mime_globs()
    if not entries:
        return None
    best = None
    # case sensitive first, then insensitive
    for insensitive in (False, True):
        candidates = []
        for (w, pattern, mstr, order) in entries:
            pat = pattern.lower() if insensitive else pattern
            name = filename.lower() if insensitive else filename
            if _glob_match(pat, name):
                candidates.append((w, len(pattern), -order, mstr))
        if candidates:
            candidates.sort(key=lambda x: (x[0], x[1], x[2]))
            best = candidates[-1][3]
            break
    if best is None:
        return None
    mk, err = parse_mime_str(best)
    if mk is None:
        return None
    # alias resolve
    ess = mk.essence()
    seen = set()
    while ess in aliases and ess not in seen:
        seen.add(ess)
        ess = aliases[ess]
        mk2, _ = parse_mime_str(ess)
        if mk2 is None:
            break
        mk = mk2
        ess = mk.essence()
    return mk

def rust_path_file_name(p):
    # Components split by '/', drop '' and '.', last component if '..' or none -> ''
    parts = []
    for comp in p.split('/'):
        if comp == '' or comp == '.':
            continue
        parts.append(comp)
    if not parts:
        return ''
    last = parts[-1]
    if last == '..':
        return ''
    return last

# ---------------------------------------------------------------------------
# Desktop entry parsing

class DesktopEntry:
    __slots__ = ('name', 'exec', 'mime_types', 'icon', 'terminal', 'path')
    def __init__(self, name, exec_, mime_types, icon, terminal, path):
        self.name = name
        self.exec = exec_
        self.mime_types = mime_types
        self.icon = icon
        self.terminal = terminal
        self.path = path

_desktop_parse_cache = {}

def parse_desktop_file(path):
    if path in _desktop_parse_cache:
        return _desktop_parse_cache[path]
    result = _parse_desktop_file_uncached(path)
    _desktop_parse_cache[path] = result
    return result

def _parse_desktop_file_uncached(path):
    try:
        with open(path, 'rb') as f:
            data = f.read()
    except OSError:
        return None
    try:
        text = data.decode('utf-8')
    except Exception:
        return None
    if text.startswith('\ufeff'):
        text = text[1:]
    sections = {}
    current = {}
    sections[''] = current
    raw_lines = text.split('\n')
    for raw in raw_lines:
        line = raw[:-1] if raw.endswith('\r') else raw
        eff = line.lstrip(' \t')
        if eff.strip(' \t') == '':
            continue
        if eff.startswith('#'):
            continue
        if eff.startswith('['):
            trimmed = eff.rstrip(' \t')
            if not trimmed.endswith(']'):
                return None
            inner = trimmed[1:-1]
            if inner == '':
                return None
            current = {}
            sections[inner] = current
            continue
        if '=' not in eff:
            return None
        key, value = eff.split('=', 1)
        current[key] = value
    desktop = sections.get('Desktop Entry')
    if desktop is None:
        return None
    name = desktop.get('Name')
    exec_ = desktop.get('Exec')
    if not name or not exec_:
        return None
    mime_types = []
    if 'MimeType' in desktop:
        mv = desktop.get('MimeType') or ''
        for seg in mv.split(';'):
            if seg == '':
                continue
            mk, err = parse_mime_str(seg)
            if mk is not None:
                mime_types.append(mk)
    return DesktopEntry(name, exec_, mime_types, desktop.get('Icon'), desktop.get('Terminal') == 'true', path)

def join_handler_candidate(app_dir, handler):
    if os.path.isabs(handler):
        return handler
    return os.path.join(app_dir, handler)

def lookup_desktop(handler):
    """Returns (candidate_path or None, entry or None). candidate set if exists."""
    for app_dir in application_dirs():
        cand = join_handler_candidate(app_dir, handler)
        if os.path.exists(cand):
            entry = parse_desktop_file(cand)
            return cand, entry
    return None, None

# ---------------------------------------------------------------------------
# Exec tokenisation / expansion

PANIC_DESKTOP_UNWRAP = ("src/common/desktop_entry.rs:65:49", "called `Option::unwrap()` on a `None` value")
PANIC_DESKTOP_REMOVE = ("src/common/desktop_entry.rs:105:18", "removal index (is 0) should be < len (is 0)")
PANIC_CONFIG_UNWRAP = ("src/config.rs:77:58", "called `Option::unwrap()` on a `None` value")
PANIC_CONFIG_REMOVE = ("src/config.rs:78:38", "removal index (is 0) should be < len (is 0)")

def tokenize_exec(s, panic_site=PANIC_DESKTOP_UNWRAP):
    tokens = []
    cur = []
    cur_started = False
    quote = None  # None, "'", '"'
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if quote == "'":
            if c == "'":
                quote = None
            else:
                cur.append(c)
            i += 1
            continue
        if quote == '"':
            if c == '"':
                quote = None
                i += 1
                continue
            if c == '\\' and i + 1 < n and s[i + 1] == '"':
                cur.append('"')
                i += 2
                continue
            cur.append(c)
            i += 1
            continue
        # unquoted
        if c in ' \t':
            if cur_started:
                tokens.append(''.join(cur))
                cur = []
                cur_started = False
            i += 1
            continue
        if c == "'" or c == '"':
            quote = c
            cur_started = True
            i += 1
            continue
        if c == '\\':
            if i + 1 >= n:
                panic(panic_site[0], panic_site[1])
            cur.append(s[i + 1])
            cur_started = True
            i += 2
            continue
        cur.append(c)
        cur_started = True
        i += 1
    if quote is not None:
        panic(panic_site[0], panic_site[1])
    if cur_started:
        tokens.append(''.join(cur))
    return tokens

FIELD_CODES = ('%f', '%F', '%u', '%U')

def expand_exec_tokens(tokens, args):
    expanded = []
    found = False
    for token in tokens:
        # find earliest field code
        best_idx = None
        best_code = None
        # scan for '%' followed by fFuU
        j = 0
        found_idx = None
        while j < len(token):
            if token[j] == '%' and j + 1 < len(token) and token[j + 1] in 'fFuU':
                found_idx = j
                break
            j += 1
        if found_idx is None:
            expanded.append(token)
        else:
            found = True
            code = token[found_idx:found_idx + 2]
            if token == code:
                expanded.extend(list(args))
            else:
                expanded.append(token[:found_idx] + ' '.join(args) + token[found_idx + 2:])
    if not found:
        expanded.extend(list(args))
    return expanded

