# Config (handlr.toml)

DEFAULT_SELECTOR = "rofi -dmenu -i -p 'Open With: '"
DEFAULT_CONFIG_TEXT = 'enable_selector = false\nselector = "rofi -dmenu -i -p \'Open With: \'"\n'

class ConfigObj:
    def __init__(self):
        self.enable_selector = False
        self.selector = DEFAULT_SELECTOR
        self.cfg_dir = None
        self.mimeapps_path = None

# ---- minimal TOML parsing (sufficient for handlr config files) ----

class TomlError(Exception):
    def __init__(self, debug_text):
        self.debug_text = debug_text

def _toml_type_name(v):
    if isinstance(v, bool):
        return 'boolean `%s`' % ('true' if v else 'false')
    if isinstance(v, str):
        return 'string "%s"' % v
    if isinstance(v, int):
        return 'integer `%d`' % v
    if isinstance(v, float):
        return 'float `%s`' % v
    if isinstance(v, list):
        return 'sequence'
    if isinstance(v, dict):
        return 'map'
    return 'value'

def _parse_toml_value(s, pos):
    # pos index into s; return (value, newpos).  Raises TomlError with rough msg.
    while pos < len(s) and s[pos] in ' \t':
        pos += 1
    if pos >= len(s):
        raise TomlError('empty')
    c = s[pos]
    if c == '"':
        # basic string, handle triple
        if s.startswith('"""', pos):
            end = s.find('"""', pos + 3)
            if end == -1:
                raise TomlError('unterminated')
            return s[pos + 3:end], end + 3
        out = []
        i = pos + 1
        while i < len(s):
            ch = s[i]
            if ch == '"':
                return ''.join(out), i + 1
            if ch == '\\' and i + 1 < len(s):
                esc = s[i + 1]
                mp = {'n': '\n', 't': '\t', 'r': '\r', '"': '"', '\\': '\\', 'b': '\b', 'f': '\f', '/': '/'}
                if esc in mp:
                    out.append(mp[esc]); i += 2; continue
                if esc == 'u' and i + 5 < len(s) + 1:
                    try:
                        out.append(chr(int(s[i + 2:i + 6], 16))); i += 6; continue
                    except Exception:
                        pass
                out.append(esc); i += 2; continue
            out.append(ch); i += 1
        raise TomlError('unterminated')
    if c == "'":
        if s.startswith("'''", pos):
            end = s.find("'''", pos + 3)
            if end == -1:
                raise TomlError('unterminated')
            return s[pos + 3:end], end + 3
        end = s.find("'", pos + 1)
        if end == -1:
            raise TomlError('unterminated')
        return s[pos + 1:end], end + 1
    if c == '[':
        # array (single line only, enough)
        end = s.find(']', pos)
        if end == -1:
            raise TomlError('unterminated array')
        inner = s[pos + 1:end].strip()
        vals = []
        if inner:
            # naive split respecting strings
            parts = []
            depth = 0; in_str = None; cur = ''
            k = 0
            while k < len(inner):
                ch = inner[k]
                if in_str:
                    cur += ch
                    if ch == in_str:
                        in_str = None
                elif ch in '"\'':
                    in_str = ch; cur += ch
                elif ch == '[':
                    depth += 1; cur += ch
                elif ch == ']':
                    depth -= 1; cur += ch
                elif ch == ',' and depth == 0:
                    parts.append(cur); cur = ''
                else:
                    cur += ch
                k += 1
            if cur.strip():
                parts.append(cur)
            for p in parts:
                v, _ = _parse_toml_value(p.strip(), 0)
                vals.append(v)
        return vals, end + 1
    if c == '{':
        end = s.find('}', pos)
        if end == -1:
            raise TomlError('unterminated table')
        return {}, end + 1
    # bare token
    m = re.match(r'[^\s,\]#]+', s[pos:])
    if not m:
        raise TomlError('bad value')
    tok = m.group(0)
    endpos = pos + len(tok)
    if tok == 'true': return True, endpos
    if tok == 'false': return False, endpos
    # datetime / numbers kept as string marker
    try:
        return int(tok.replace('_', ''), 10), endpos
    except Exception:
        pass
    try:
        return float(tok.replace('_', '')), endpos
    except Exception:
        pass
    return ('__bare__', tok), endpos

def parse_handlr_toml(text):
    """Return dict of top-level keys. Raises TomlError(debug_text_for_panic)."""
    root = {}
    current = root
    seen_keys = set()
    lines = text.split('\n')
    offset = 0  # byte offset of line start in text (approx, chars)
    for lineno, raw_line in enumerate(lines):
        line = raw_line
        # strip comment outside strings
        stripped = line.strip()
        line_start_offset = offset
        offset += len(raw_line) + 1
        if not stripped:
            continue
        if stripped.startswith('#'):
            continue
        if stripped.startswith('['):
            if stripped.startswith('[['):
                current = {}
                continue
            if not stripped.endswith(']'):
                raise TomlError(_bad_toml_debug('Wanted { expected: "a right bracket", found: "a newline" }', lineno, len(line), line_start_offset + len(line)))
            sect = stripped[1:-1].strip()
            current = {}
            # store under a key that won't collide with flat keys
            root['__section__' + sect] = current
            continue
        # key = value
        # find '=' outside quotes
        eq = -1; in_str = None
        for idx, ch in enumerate(line):
            if in_str:
                if ch == in_str and (idx == 0 or line[idx - 1] != '\\'):
                    in_str = None
            elif ch in '"\'':
                in_str = ch
            elif ch == '=':
                eq = idx; break
            elif ch == '#':
                break
        if eq == -1:
            # mimic toml crate: wanted an equals
            # find first unexpected char similar to original for simple cases
            first_word_end = len(line)
            raise TomlError(_bad_toml_debug('Wanted { expected: "an equals", found: "an identifier" }', lineno, min(8, len(line)), line_start_offset + min(8, len(line))))
        key = line[:eq].strip().strip('"').strip("'")
        if not key:
            raise TomlError(_bad_toml_debug('Wanted { expected: "a key", found: "an equals" }', lineno, eq, line_start_offset + eq))
        val_str = line[eq + 1:]
        # strip comment outside string later; _parse accepts trailing
        try:
            val, vpos = _parse_toml_value(val_str, 0)
        except TomlError:
            # unexpected char errors for simple things: 'bad !'
            raise
        if isinstance(val, tuple) and val and val[0] == '__bare__':
            # invalid bare value like an identifier
            tok = val[1]
            # position of token
            col = eq + 1 + (len(val_str) - len(val_str.lstrip()))
            raise TomlError(_bad_toml_debug("Unexpected('%s')" % tok[0] if tok else 'Custom', lineno, col, line_start_offset + col))
        # duplicate key check within current table
        marker = (id(current), key)
        if marker in seen_keys:
            raise TomlError(_bad_toml_debug('Custom', lineno, eq, line_start_offset + eq, message='duplicate key: `%s`' % key))
        seen_keys.add(marker)
        current[key] = (val, val_str, eq, line_start_offset, lineno)
    return root

def _bad_toml_debug(kind, line, col, at, message=''):
    return 'Error { inner: ErrorInner { kind: %s, line: Some(%d), col: %d, at: Some(%d), message: "%s", key: [] } }' % (kind, line, col, at, message)

def load_config():
    cfg = ConfigObj()
    cfgdir = config_dir_path()
    cfg.cfg_dir = cfgdir
    if cfgdir is None:
        return cfg
    cfg.mimeapps_path = os.path.join(cfgdir, 'mimeapps.list')
    handlr_dir = os.path.join(cfgdir, 'handlr')
    toml_path = os.path.join(handlr_dir, 'handlr.toml')
    # create handlr dir
    if os.path.isdir(handlr_dir):
        pass
    elif os.path.lexists(handlr_dir):
        # exists as a file: falling through will fail on toml creation (ENOTDIR)
        pass
    else:
        try:
            os.makedirs(handlr_dir, exist_ok=True)
        except OSError as e:
            if e.errno == 20:  # NotADirectory
                panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: GeneralLoadError(%s)" % os_debug_exc(e))
            else:
                panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: DirectoryCreationFailed(%s)" % os_debug_exc(e))
    # toml file
    if os.path.isdir(toml_path):
        panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: ReadConfigurationFileError(%s)" % os_debug_from_errno(21))
    if not os.path.exists(toml_path):
        try:
            with open(toml_path, 'w', encoding='utf-8', newline='\n') as f:
                f.write(DEFAULT_CONFIG_TEXT)
        except OSError as e:
            panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: GeneralLoadError(%s)" % os_debug_exc(e))
    # read it
    try:
        with open(toml_path, 'rb') as f:
            data = f.read()
    except OSError as e:
        if e.errno == 21:
            panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: ReadConfigurationFileError(%s)" % os_debug_exc(e))
        panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: GeneralLoadError(%s)" % os_debug_exc(e))
    try:
        text = data.decode('utf-8')
    except Exception:
        panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: BadTomlData(%s)" % _bad_toml_debug('Custom', 0, 0, 0, 'invalid utf-8'))
    try:
        root = parse_handlr_toml(text)
    except TomlError as te:
        panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: BadTomlData(%s)" % te.debug_text)
    # extract fields
    for key, expected in (('enable_selector', 'bool'), ('selector', 'str')):
        if key in root and not isinstance(root[key], dict):
            val, val_str, eq, line_off, lineno = root[key]
            if expected == 'bool' and not isinstance(val, bool):
                col = eq + 1 + (len(val_str) - len(val_str.lstrip()))
                msg = 'invalid type: %s, expected a boolean' % _toml_type_name(val)
                dbg = 'Error { inner: ErrorInner { kind: Custom, line: Some(%d), col: %d, at: Some(%d), message: "%s", key: ["%s"] } }' % (lineno, col, line_off + col, msg, key)
                panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: BadTomlData(%s)" % dbg)
            if expected == 'str' and not isinstance(val, str):
                col = eq + 1 + (len(val_str) - len(val_str.lstrip()))
                msg = 'invalid type: %s, expected a string' % _toml_type_name(val)
                dbg = 'Error { inner: ErrorInner { kind: Custom, line: Some(%d), col: %d, at: Some(%d), message: "%s", key: ["%s"] } }' % (lineno, col, line_off + col, msg, key)
                panic("src/config.rs:63:31", "called `Result::unwrap()` on an `Err` value: BadTomlData(%s)" % dbg)
            if key == 'enable_selector':
                cfg.enable_selector = bool(val)
            else:
                cfg.selector = val
    return cfg

def config_select(cfg, names):
    tokens = tokenize_exec(cfg.selector, panic_site=PANIC_CONFIG_UNWRAP)
    if not tokens:
        panic(PANIC_CONFIG_REMOVE[0], PANIC_CONFIG_REMOVE[1])
    binary = tokens[0]
    rest = tokens[1:]
    try:
        proc = subprocess.Popen([binary] + rest, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=None)
    except OSError:
        return None
    input_data = '\n'.join(names).encode('utf-8')
    try:
        out, _ = proc.communicate(input=input_data)
    except Exception:
        try:
            out = proc.stdout.read() if proc.stdout else b''
        except Exception:
            out = b''
    if out is None:
        out = b''
    selected = out.decode('utf-8', 'replace')
    # trim_end (Rust trim_end trims whitespace incl unicode)
    selected = re.sub(r'\s+$', '', selected, flags=re.UNICODE)
    if selected == '':
        return None
    return selected

