# URL handling

SPECIAL_SCHEMES = {'http': 80, 'https': 443, 'ws': 80, 'wss': 443, 'ftp': 21, 'file': None}

def _pct_encode(s, encode_set, preserve_pct=True):
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        if preserve_pct and ch == '%':
            out.append('%'); i += 1; continue
        o = ord(ch)
        if o < 0x20 or o == 0x7f or o > 0x7e or ch in encode_set:
            for b in ch.encode('utf-8'):
                out.append('%%%02X' % b)
        else:
            out.append(ch)
        i += 1
    return ''.join(out)

def _encode_path_segment(seg):
    return _pct_encode(seg, set(' "<>?#'))

def _encode_query(q):
    return _pct_encode(q, set(' "#'))

def _encode_fragment(f):
    return _pct_encode(f, set(' "<>`'))

def _encode_userinfo(u):
    return _pct_encode(u, set(' /?:@[]'))

def _ipv4_canonical(host):
    parts = host.split('.')
    if len(parts) > 4:
        return None
    nums = []
    for p in parts:
        if p == '':
            return None
        try:
            if p.lower().startswith('0x'):
                v = int(p, 16)
            elif len(p) > 1 and p[0] == '0' and p.isdigit():
                v = int(p, 8)
            elif p.isdigit():
                v = int(p, 10)
            else:
                return None
        except Exception:
            return None
        nums.append(v)
    # validate
    for v in nums[:-1]:
        if v > 255:
            return None
    last_max = 256 ** (5 - len(nums))
    if nums[-1] >= last_max:
        return None
    addr = 0
    for idx, v in enumerate(nums[:-1]):
        addr += v * (256 ** (3 - idx))
    addr += nums[-1]
    return str(ipaddress.IPv4Address(addr))

def _host_serialize(host, special):
    if host == '':
        return None
    if host.startswith('['):
        # ipv6
        end = host.find(']')
        if end == -1:
            return None
        inside = host[1:end]
        try:
            ip = ipaddress.IPv6Address(inside)
            return '[' + ip.compressed + ']', host[end + 1:]
        except Exception:
            return None
    # split host/port is done by caller for authority case
    h = host
    if special:
        # percent or spaces invalid
        if any(ord(c) <= 0x20 or ord(c) == 0x7f for c in h):
            return None
        hl = h.lower()
        # ipv4 attempt: if last part numeric-ish
        parts = hl.split('.')
        last = parts[-1] if parts else ''
        numeric_last = False
        if last:
            if last.isdigit() or last.lower().startswith('0x'):
                numeric_last = True
        if numeric_last:
            canon = _ipv4_canonical(hl)
            if canon is not None:
                return canon
            # else fall through as domain
        # IDNA
        labels = hl.split('.')
        out_labels = []
        for lab in labels:
            if lab == '':
                out_labels.append('')
                continue
            if all(ord(c) < 128 for c in lab):
                out_labels.append(lab)
            else:
                try:
                    enc = lab.encode('idna').decode('ascii')
                    out_labels.append(enc)
                except Exception:
                    try:
                        enc = lab.encode('punycode').decode('ascii')
                        out_labels.append('xn--' + enc)
                    except Exception:
                        out_labels.append(lab)
        return '.'.join(out_labels)
    else:
        return h

class ParsedUrl:
    def __init__(self):
        self.scheme = ''
        self.is_special = False
        self.has_authority = False
        self.username = ''
        self.password = None
        self.host = None
        self.host_raw = None
        self.port = None
        self.path_segments = []  # encoded segments, path starts with / if non-empty for authority
        self.path_str = ''  # serialized path
        self.query = None
        self.fragment = None
        self.opaque_path = None
        self.file_host_bad = False
        self.file_path_str = None
        self.file_path_display = '/'
        self.file_invalid_utf8 = False

def _split_authority(rest_after_slashes):
    # returns (authority, remainder starting with delimiter or '')
    idx = len(rest_after_slashes)
    for delim in ('/', '\\', '?', '#'):
        j = rest_after_slashes.find(delim)
        if j != -1 and j < idx:
            idx = j
    return rest_after_slashes[:idx], rest_after_slashes[idx:]

def _parse_authority(auth, special):
    # returns (username,password,host_serialized,port) or None
    username = ''
    password = None
    hostport = auth
    if '@' in auth:
        userinfo, hostport = auth.rsplit('@', 1)
        if ':' in userinfo:
            username, password = userinfo.split(':', 1)
        else:
            username = userinfo
        username = _encode_userinfo(username)
        if password is not None:
            password = _pct_encode(password, set(' /?:@[]'))
    host = hostport
    port = None
    if hostport.startswith('['):
        end = hostport.find(']')
        if end == -1:
            return None
        host = hostport[:end + 1]
        restp = hostport[end + 1:]
        if restp:
            if not restp.startswith(':'):
                return None
            pstr = restp[1:]
            if pstr == '':
                port = None
            elif not pstr.isdigit():
                return None
            else:
                port = int(pstr)
                if port > 65535:
                    return None
        hs = _host_serialize(host, special)
        if hs is None:
            return None
        host_s = hs[0] if isinstance(hs, tuple) else hs
        return username, password, host_s, port
    else:
        if ':' in hostport:
            # last colon
            hpart, pstr = hostport.rsplit(':', 1)
            if ':' in hpart:
                return None
            host = hpart
            if pstr == '':
                port = None
            elif not pstr.isdigit():
                return None
            else:
                port = int(pstr)
                if port > 65535:
                    return None
        if host == '':
            return None
        hs = _host_serialize(host, special)
        if hs is None:
            return None
        host_s = hs[0] if isinstance(hs, tuple) else hs
        return username, password, host_s, port

def _normalize_path_segments(path_raw, special):
    # path_raw starts maybe; returns list of encoded segments (without leading slash), trailing_slash flag
    # Split on / (and \ if special)
    if special:
        parts = re.split(r'[/\\]', path_raw)
    else:
        parts = path_raw.split('/')
    # path_raw expected to start with '/', first part ''
    segments = []
    trailing = False
    # We'll process parts after handling leading slash in caller
    for idx, part in enumerate(parts):
        is_last = idx == len(parts) - 1
        low = part.lower()
        if low in ('.', '%2e'):
            if is_last:
                trailing = True
            continue
        if low in ('..', '.%2e', '%2e.', '%2e%2e'):
            if segments:
                segments.pop()
            if is_last:
                trailing = True
            continue
        segments.append(_encode_path_segment(part))
        trailing = False
    if path_raw.endswith('/') or path_raw.endswith('\\') and special:
        trailing = True
    return segments, trailing

def parse_url(raw):
    s = raw.replace('\t', '').replace('\n', '').replace('\r', '')
    s = s.strip(''.join(chr(i) for i in range(0x21)))
    m = re.match(r'^([A-Za-z][A-Za-z0-9+.\-]*):(.*)$', s, re.DOTALL)
    if not m:
        return None
    scheme = m.group(1).lower()
    rest = m.group(2)
    url = ParsedUrl()
    url.scheme = scheme
    special = scheme in SPECIAL_SCHEMES
    url.is_special = special
    # split fragment / query for path handling later, but keep delimiters in rest parsing
    if scheme == 'file':
        return _parse_file_url(url, rest)
    if special:
        # strip leading slashes/backslashes
        stripped = rest.lstrip('/\\')
        if stripped == '':
            return None
        auth, remainder = _split_authority(stripped)
        if auth == '':
            return None
        parsed = _parse_authority(auth, True)
        if parsed is None:
            return None
        username, password, host_s, port = parsed
        if port is not None and SPECIAL_SCHEMES.get(scheme) == port:
            port = None
        url.username = username; url.password = password; url.host = host_s; url.port = port; url.has_authority = True
        # remainder is path/query/fragment
        pqf = remainder
        # split fragment
        frag = None; query = None
        if '#' in pqf:
            pqf, frag = pqf.split('#', 1)
        if '?' in pqf:
            pqf, q = pqf.split('?', 1)
            query = q
        if pqf == '':
            segs = []; trailing = True
            path_str = '/'
        else:
            segs, trailing = _normalize_path_segments(pqf, True)
            path_str = '/' + '/'.join(segs)
            if trailing and not path_str.endswith('/'):
                path_str += '/'
            if segs and pqf == '':
                path_str = '/'
        url.path_str = path_str
        url.query = _encode_query(query) if query is not None else None
        url.fragment = _encode_fragment(frag) if frag is not None else None
        return url
    else:
        # non-special
        frag = None; query = None
        main = rest
        if '#' in main:
            main, frag = main.split('#', 1)
        if '?' in main:
            main, q = main.split('?', 1)
            query = q
        if main.startswith('//'):
            after = main[2:]
            # authority until slash
            idx = after.find('/')
            if idx == -1:
                auth = after; path_raw = ''
            else:
                auth = after[:idx]; path_raw = after[idx:]
            if auth == '':
                # treat whole main as opaque-ish path
                url.has_authority = False
                url.opaque_path = main
                url.path_str = main
            else:
                parsed = _parse_authority(auth, False)
                if parsed is None:
                    return None
                username, password, host_s, port = parsed
                url.username = username; url.password = password; url.host = host_s; url.port = port; url.has_authority = True
                if path_raw == '':
                    url.path_str = ''
                else:
                    segs, trailing = _normalize_path_segments(path_raw, False)
                    path_str = '/' + '/'.join(segs)
                    if trailing and not path_str.endswith('/'):
                        path_str += '/'
                    url.path_str = path_str
        else:
            url.has_authority = False
            # opaque path: encode non-ascii / controls only, preserve spaces
            url.opaque_path = _pct_encode(main, set(), preserve_pct=True) if False else _encode_opaque(main)
            url.path_str = url.opaque_path
        url.query = _encode_query(query) if query is not None else None
        url.fragment = _encode_fragment(frag) if frag is not None else None
        return url

def _encode_opaque(s):
    out = []
    for ch in s:
        o = ord(ch)
        if o < 0x20 or o == 0x7f or o > 0x7e:
            for b in ch.encode('utf-8'):
                out.append('%%%02X' % b)
        else:
            out.append(ch)
    return ''.join(out)

def _parse_file_url(url, rest):
    url.is_special = True
    url.has_authority = True
    main = rest
    frag = None; query = None
    if '#' in main:
        main, frag = main.split('#', 1)
    if '?' in main:
        main, q = main.split('?', 1)
        query = q
    host = ''
    path_raw = main
    if main.startswith('//'):
        after = main[2:]
        # authority until / or backslash
        idx = len(after)
        for delim in ('/', '\\'):
            j = after.find(delim)
            if j != -1 and j < idx:
                idx = j
        host = after[:idx]
        path_raw = after[idx:] if idx < len(after) else ''
    elif main.startswith('/') or main == '':
        host = ''
        path_raw = main
    else:
        # file:relative  -> path is relative name, will be rooted
        host = ''
        path_raw = main
    host_low = host.lower()
    # normalize path segments encoded
    if path_raw == '':
        segs_enc = []
        trailing = True
    else:
        pr = path_raw if path_raw.startswith('/') else '/' + path_raw
        segs_enc, trailing = _normalize_path_segments(pr, True)
    display_path = '/' + '/'.join(segs_enc)
    if (trailing or not segs_enc) and not display_path.endswith('/'):
        # For file path, if original ended without slash, don't force unless empty
        if not segs_enc:
            display_path = '/'
    url.file_path_display = display_path if display_path else '/'
    # drive letter check
    drive = False
    if segs_enc:
        first = segs_enc[0]
        if re.match(r'^[A-Za-z]:$', first) or re.match(r'^[A-Za-z]\|$', first):
            drive = True
    if host_low not in ('', 'localhost') and not drive:
        url.file_host_bad = True
    # decode segments to path string
    decoded_segments = []
    invalid = False
    for seg in segs_enc:
        # percent decode
        bs = bytearray()
        i = 0
        while i < len(seg):
            if seg[i] == '%' and i + 2 < len(seg) and all(c in '0123456789abcdefABCDEF' for c in seg[i + 1:i + 3]):
                bs.append(int(seg[i + 1:i + 3], 16)); i += 3
            else:
                bs.extend(seg[i].encode('utf-8')); i += 1
        try:
            dec = bytes(bs).decode('utf-8')
        except Exception:
            invalid = True
            dec = bytes(bs).decode('utf-8', 'replace')
        decoded_segments.append(dec)
    url.file_invalid_utf8 = invalid
    fpath = '/' + '/'.join(decoded_segments)
    if trailing and decoded_segments and not fpath.endswith('/'):
        # preserve trailing slash if original path_raw ended with slash (decoded path will be checked is_dir anyway)
        if path_raw.endswith('/') or path_raw.endswith('\\'):
            fpath += '/'
    if not decoded_segments:
        fpath = '/'
    url.file_path_str = fpath
    url.path_str = display_path
    url.query = query
    url.fragment = frag
    return url

def url_serialize(url):
    if url.scheme == 'file':
        return url.file_path_str or '/'
    parts = [url.scheme, ':']
    if url.has_authority:
        parts.append('//')
        if url.username:
            parts.append(url.username)
            if url.password is not None:
                parts.append(':' + url.password)
            parts.append('@')
        elif url.password is not None:
            # username empty but password present: original keeps :pass@
            parts.append(':' + url.password + '@')
        if url.host:
            parts.append(url.host)
        if url.port is not None:
            parts.append(':%d' % url.port)
        parts.append(url.path_str)
    else:
        parts.append(url.path_str)
    if url.query is not None:
        parts.append('?' + url.query)
    if url.fragment is not None:
        parts.append('#' + url.fragment)
    return ''.join(parts)

