def validate_mime_value(s):
    if s.startswith('.'):
        filename = rust_path_file_name(s)
        mk = guess_mime_by_filename(filename) if filename else None
        if mk is None or mk.essence() in ('application/x-zerosize', 'application/octet-stream'):
            return "could not figure out the mime type of '%s'" % s
        return None
    mk, err = parse_mime_str(s)
    if err is not None:
        return err
    if mk is not None and mk.sub == '':
        return 'bad mime: %s' % s
    return None

def mime_from_validated(s):
    if s.startswith('.'):
        filename = rust_path_file_name(s)
        mk = guess_mime_by_filename(filename)
        return mk
    mk, _ = parse_mime_str(s)
    return mk

def validate_handler_value(s):
    cand, entry = lookup_desktop(s)
    if cand is None:
        return "no handlers found for '%s'" % s
    if entry is None:
        return 'malformed desktop entry at %s' % cand
    return None

def validate_path_value(s):
    url = parse_url(s)
    if url is not None and url.scheme == 'file' and url.file_host_bad:
        return 'Bad path: %s' % url.file_path_display
    return None

