def format_table(rows):
    if not rows:
        return "┌──┐\n│  │\n└──┘\n"
    col_count = len(rows[0])
    widths = [0] * col_count
    for r in rows:
        for idx, cell in enumerate(r):
            widths[idx] = max(widths[idx], _cell_width(cell))
    top = "┌" + "┬".join("─" * (w + 2) for w in widths) + "┐\n"
    out = [top]
    for r in rows:
        line = "│"
        for idx, cell in enumerate(r):
            line += " " + cell + " " * (widths[idx] - _cell_width(cell)) + " │"
        out.append(line + "\n")
    bottom = "└" + "┴".join("─" * (w + 2) for w in widths) + "┘\n"
    out.append(bottom)
    return ''.join(out)

