# Desktop entry parsing

class DesktopEntry:
    __slots__ = ('name', 'exec', 'mime_types', 'icon', 'terminal', 'path')
    def __init__(self, name, exec_, mime_types, icon, terminal, path):
        self.name = name
        self.exec = exec_
        self.mime_types = mime_types
        self.icon = icon
        self.terminal = terminal
        self.path = path

_desktop_parse_cache = {}

def parse_desktop_file(path):
    if path in _desktop_parse_cache:
        return _desktop_parse_cache[path]
    result = _parse_desktop_file_uncached(path)
    _desktop_parse_cache[path] = result
    return result

def _parse_desktop_file_uncached(path):
    try:
        with open(path, 'rb') as f:
            data = f.read()
    except OSError:
        return None
    try:
        text = data.decode('utf-8')
    except Exception:
        return None
    if text.startswith('\ufeff'):
        text = text[1:]
    sections = {}
    current = {}
    sections[''] = current
    raw_lines = text.split('\n')
    for raw in raw_lines:
        line = raw[:-1] if raw.endswith('\r') else raw
        eff = line.lstrip(' \t')
        if eff.strip(' \t') == '':
            continue
        if eff.startswith('#'):
            continue
        if eff.startswith('['):
            trimmed = eff.rstrip(' \t')
            if not trimmed.endswith(']'):
                return None
            inner = trimmed[1:-1]
            if inner == '':
                return None
            current = {}
            sections[inner] = current
            continue
        if '=' not in eff:
            return None
        key, value = eff.split('=', 1)
        current[key] = value
    desktop = sections.get('Desktop Entry')
    if desktop is None:
        return None
    name = desktop.get('Name')
    exec_ = desktop.get('Exec')
    if not name or not exec_:
        return None
    mime_types = []
    if 'MimeType' in desktop:
        mv = desktop.get('MimeType') or ''
        for seg in mv.split(';'):
            if seg == '':
                continue
            mk, err = parse_mime_str(seg)
            if mk is not None:
                mime_types.append(mk)
    return DesktopEntry(name, exec_, mime_types, desktop.get('Icon'), desktop.get('Terminal') == 'true', path)

def join_handler_candidate(app_dir, handler):
    if os.path.isabs(handler):
        return handler
    return os.path.join(app_dir, handler)

def lookup_desktop(handler):
    """Returns (candidate_path or None, entry or None). candidate set if exists."""
    for app_dir in application_dirs():
        cand = join_handler_candidate(app_dir, handler)
        if os.path.exists(cand):
            entry = parse_desktop_file(cand)
            return cand, entry
    return None, None

# ---------------------------------------------------------------------------
# Exec tokenisation / expansion

PANIC_DESKTOP_UNWRAP = ("src/common/desktop_entry.rs:65:49", "called `Option::unwrap()` on a `None` value")
PANIC_DESKTOP_REMOVE = ("src/common/desktop_entry.rs:105:18", "removal index (is 0) should be < len (is 0)")
PANIC_CONFIG_UNWRAP = ("src/config.rs:77:58", "called `Option::unwrap()` on a `None` value")
PANIC_CONFIG_REMOVE = ("src/config.rs:78:38", "removal index (is 0) should be < len (is 0)")

def tokenize_exec(s, panic_site=PANIC_DESKTOP_UNWRAP):
    tokens = []
    cur = []
    cur_started = False
    quote = None  # None, "'", '"'
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if quote == "'":
            if c == "'":
                quote = None
            else:
                cur.append(c)
            i += 1
            continue
        if quote == '"':
            if c == '"':
                quote = None
                i += 1
                continue
            if c == '\\' and i + 1 < n and s[i + 1] == '"':
                cur.append('"')
                i += 2
                continue
            cur.append(c)
            i += 1
            continue
        # unquoted
        if c in ' \t':
            if cur_started:
                tokens.append(''.join(cur))
                cur = []
                cur_started = False
            i += 1
            continue
        if c == "'" or c == '"':
            quote = c
            cur_started = True
            i += 1
            continue
        if c == '\\':
            if i + 1 >= n:
                panic(panic_site[0], panic_site[1])
            cur.append(s[i + 1])
            cur_started = True
            i += 2
            continue
        cur.append(c)
        cur_started = True
        i += 1
    if quote is not None:
        panic(panic_site[0], panic_site[1])
    if cur_started:
        tokens.append(''.join(cur))
    return tokens

FIELD_CODES = ('%f', '%F', '%u', '%U')

def expand_exec_tokens(tokens, args):
    expanded = []
    found = False
    for token in tokens:
        # find earliest field code
        best_idx = None
        best_code = None
        # scan for '%' followed by fFuU
        j = 0
        found_idx = None
        while j < len(token):
            if token[j] == '%' and j + 1 < len(token) and token[j + 1] in 'fFuU':
                found_idx = j
                break
            j += 1
        if found_idx is None:
            expanded.append(token)
        else:
            found = True
            code = token[found_idx:found_idx + 2]
            if token == code:
                expanded.extend(list(args))
            else:
                expanded.append(token[:found_idx] + ' '.join(args) + token[found_idx + 2:])
    if not found:
        expanded.extend(list(args))
    return expanded

