# MimeApps (user) and System apps

class Apps:
    def __init__(self, cfg):
        self.cfg = cfg
        self.defaults = {}
        self.added = {}
        self.system = {}
        self._load_system()
        self._load_user()

    # -------- system --------
    def _load_system(self):
        seen = set()
        for app_dir in application_dirs():
            try:
                entries = list(os.scandir(app_dir))
            except OSError:
                continue
            for entry in entries:
                name = entry.name
                if name in seen:
                    continue
                if not name.endswith('.desktop'):
                    continue
                seen.add(name)
                path = os.path.join(app_dir, name)
                de = parse_desktop_file(path)
                if de is None:
                    continue
                for mk in de.mime_types:
                    self.system.setdefault(mk, []).append(name)

    # -------- user --------
    def _user_panic_io(self, e):
        panic("src/apps/user.rs:12:65", "called `Result::unwrap()` on an `Err` value: Io(%s)" % os_debug_exc(e))

    def _load_user(self):
        cfg = self.cfg
        if cfg.mimeapps_path is None:
            return
        path = cfg.mimeapps_path
        # open read/write, create if missing (like OpenOptions)
        try:
            fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o644)
        except OSError as e:
            self._user_panic_io(e)
        try:
            data = b''
            while True:
                chunk = os.read(fd, 65536)
                if not chunk:
                    break
                data += chunk
        except OSError as e:
            try: os.close(fd)
            except Exception: pass
            self._user_panic_io(e)
        try:
            os.close(fd)
        except Exception:
            pass
        try:
            text = data.decode('utf-8')
        except Exception:
            panic("src/apps/user.rs:12:65", 'called `Result::unwrap()` on an `Err` value: Io(Custom { kind: InvalidData, error: "stream did not contain valid UTF-8" })')
        defaults, added = parse_mimeapps_text(text, self)
        self.defaults = defaults
        self.added = added

    def save_user(self):
        cfg = self.cfg
        if cfg.mimeapps_path is None:
            io_not_found()
        out = self._serialize_user()
        try:
            with open(cfg.mimeapps_path, 'wb') as f:
                f.write(out.encode('utf-8'))
        except OSError as e:
            raise MainError('Io(%s)' % os_debug_exc(e))

    def _serialize_user(self):
        parts = ['[Added Associations]\n']
        for mk in sorted(self.added.keys(), key=lambda m: m.canonical()):
            parts.append('%s=%s;\n' % (mk.essence(), ';'.join(self.added[mk])))
        parts.append('\n[Default Applications]\n')
        for mk in sorted(self.defaults.keys(), key=lambda m: m.canonical()):
            parts.append('%s=%s;\n' % (mk.essence(), ';'.join(self.defaults[mk])))
        return ''.join(parts)

    # -------- handler resolution --------
    def _find_handlers_names(self, handler_tokens):
        # returns list of (token, name) for tokens that resolve
        res = []
        for tok in handler_tokens:
            cand, entry = lookup_desktop(tok)
            if entry is not None:
                res.append((tok, entry.name))
            else:
                res.append((tok, tok))
        return res

    def resolve_handler_token(self, mime):
        """Return handler token (desktop file name) or None following get logic."""
        cfg = self.cfg
        # A. defaults exact or wildcard
        lst = None
        if mime in self.defaults:
            lst = self.defaults[mime]
        else:
            wild, _ = parse_mime_str('%s/*' % mime.typ)
            if wild in self.defaults:
                lst = self.defaults[wild]
        if lst:
            if cfg.enable_selector and len(lst) > 1:
                named = []
                for tok in lst:
                    cand, entry = lookup_desktop(tok)
                    named.append(entry.name if entry is not None else tok)
                sel = config_select(cfg, named)
                if sel is None:
                    return lst[0]
                # find by name
                for tok, nm in zip(lst, named):
                    if nm == sel:
                        return tok
                panic("src/apps/user.rs:67:26", "called `Option::unwrap()` on a `None` value")
            return lst[0]
        # B. added exact
        if mime in self.added and self.added[mime]:
            return self.added[mime][0]
        # C. system exact
        if mime in self.system and self.system[mime]:
            return self.system[mime][0]
        return None

    def full_handler(self, mime, args):
        """Return (token, name, cmd_string, command_tokens) or raise MainError.
        command_tokens is the full token list including binary."""
        token = self.resolve_handler_token(mime)
        if token is None:
            io_not_found()
        cand, entry = lookup_desktop(token)
        if entry is None:
            io_not_found()
        tokens = self._entry_command_tokens(entry, args)
        return token, entry.name, tokens

    def _entry_command_tokens(self, entry, args):
        if entry.terminal:
            term_mime, _ = parse_mime_str('x-scheme-handler/terminal')
            term_token = self.resolve_handler_token(term_mime)
            if term_token is None:
                io_not_found()
            tcand, tentry = lookup_desktop(term_token)
            if tentry is None:
                io_not_found()
            term_tokens = tokenize_exec(tentry.exec)
            app_tokens = expand_exec_tokens(tokenize_exec(entry.exec), list(args))
            return term_tokens + ['-e'] + app_tokens
        else:
            return expand_exec_tokens(tokenize_exec(entry.exec), list(args))

    def get_cmd_string(self, mime):
        token, name, tokens = self.full_handler(mime, [])
        if not tokens:
            panic(PANIC_DESKTOP_REMOVE[0], PANIC_DESKTOP_REMOVE[1])
        binary = tokens[0]
        rest = tokens[1:]
        return token, name, '%s %s' % (binary, ' '.join(rest))

    def execute_handler(self, mime, args):
        token, name, tokens = self.full_handler(mime, list(args))
        if not tokens:
            panic(PANIC_DESKTOP_REMOVE[0], PANIC_DESKTOP_REMOVE[1])
        binary = tokens[0]
        rest = tokens[1:]
        spawn_detached(binary, rest)

_spawned = []

def spawn_detached(binary, rest):
    try:
        p = subprocess.Popen([binary] + list(rest), stdin=None, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, close_fds=True)
        _spawned.append(p)
    except OSError:
        io_not_found()
    except ValueError:
        io_not_found()

# -------- mimeapps grammar --------

def _is_name_char(ch):
    if ch in '$<>^`|~':
        return False
    if ch == '+':
        return True
    cat = unicodedata.category(ch)
    if cat[0] in ('L', 'M', 'N', 'P') or ch == ' ':
        return True
    return False

def _is_section_char(ch):
    cat = unicodedata.category(ch)
    if cat[0] in ('L', 'M', 'N') or ch in (' ', '-', '_', '='):
        return True
    return False

def _is_value_char(ch):
    cat = unicodedata.category(ch)
    if cat[0] == 'C':
        return False
    return True

class MimeappsParseFailure(Exception):
    def __init__(self, byte_pos, line_no, col_no, line_text, has_newline, positives):
        self.byte_pos = byte_pos
        self.line_no = line_no
        self.col_no = col_no
        self.line_text = line_text
        self.has_newline = has_newline
        self.positives = positives

def _pest_line_repr(line_text, has_newline):
    inner = ''
    for ch in line_text:
        o = ord(ch)
        if ch == '"': inner += '\\"'
        elif ch == '\\': inner += '\\\\'
        elif ch == '\t': inner += '\\t'
        elif ch == '\r': inner += '\\r'
        elif o == 0: inner += '\\0'
        elif o < 0x20 or o == 0x7f: inner += '\\u{%x}' % o
        else: inner += ch
    if has_newline:
        inner += '\u240a'
    return '"%s"' % inner

def parse_mimeapps_text(text, apps):
    # returns (defaults, added)
    # enforce trailing newline
    physical = text.split('\n')
    # If text ends with \n, last split piece is '' sentinel
    ends_with_nl = text.endswith('\n') or text == ''
    lines = []
    if text == '':
        lines = []
    else:
        # physical lines without newline char; drop final sentinel if ends with nl
        raw_lines = physical[:-1] if ends_with_nl else physical
        for idx, rl in enumerate(raw_lines):
            has_nl = ends_with_nl or idx < len(raw_lines) - 1
            # Actually each line except possibly last has newline
            has_nl = True if idx < len(raw_lines) - 1 else ends_with_nl
            ln = rl[:-1] if rl.endswith('\r') else rl
            lines.append((ln, has_nl, rl))
    if text != '' and not ends_with_nl:
        # failure on last line
        ln, _, _ = lines[-1]
        # compute position
        byte_pos = len(text.encode('utf-8'))
        line_no = len(lines)
        col_no = len(ln) + 1
        if ln.startswith('#'):
            positives = ['name_char']
        elif ln.startswith('['):
            positives = ['section_char']
        elif '=' in ln:
            positives = ['value_char']
        elif ln == '':
            positives = ['value_char']
        else:
            positives = ['name_char']
        raise MimeappsParseFailure(byte_pos, line_no, col_no, ln, False, positives)
    defaults = {}
    added = {}
    removed = {}
    current_name = None
    # byte offsets per line
    offset = 0
    for (ln, has_nl, raw_with_cr) in lines:
        line_bytes_len = len((raw_with_cr + '\n').encode('utf-8')) if has_nl else len(raw_with_cr.encode('utf-8'))
        line_start = offset
        offset += line_bytes_len
        if ln == '':
            continue
        if ln.startswith('#'):
            for j, ch in enumerate(ln[1:]):
                if not _is_name_char(ch):
                    byte_pos = line_start + len(ln[:1 + j].encode('utf-8'))
                    raise MimeappsParseFailure(byte_pos, lines.index((ln, has_nl, raw_with_cr)) + 1 if False else 0, 0, ln, has_nl, ['name_char'])
            continue
        if ln.startswith('['):
            # section
            if not ln.endswith(']') or len(ln) < 3:
                # location at first ']' if any else at end
                if ']' in ln:
                    pos_chars = ln.index(']')
                    byte_pos = line_start + len(ln[:pos_chars].encode('utf-8'))
                    col = pos_chars + 1
                else:
                    byte_pos = line_start + len(ln.encode('utf-8'))
                    col = len(ln) + 1
                # line number computed below generically - we recompute in handler
                fail = MimeappsParseFailure(byte_pos, 0, col, ln, has_nl, ['section_char'])
                fail._line_no_raw = None
                raise fail
            inner = ln[1:-1]
            if inner == '':
                byte_pos = line_start + 1
                fail = MimeappsParseFailure(byte_pos, 0, 2, ln, has_nl, ['name_char'])
                raise fail
            bad = None
            for j, ch in enumerate(inner):
                if not _is_section_char(ch):
                    bad = j; break
            if bad is not None:
                if ']' in ln:
                    pos_chars = ln.index(']')
                    byte_pos = line_start + len(ln[:pos_chars].encode('utf-8'))
                    col = pos_chars + 1
                else:
                    byte_pos = line_start + len(ln.encode('utf-8')); col = len(ln) + 1
                raise MimeappsParseFailure(byte_pos, 0, col, ln, has_nl, ['section_char'])
            current_name = inner
            continue
        # entry line
        if ln[0] == '\t' or ln[0] == '\x00':
            raise MimeappsParseFailure(line_start, 0, 1, ln, has_nl, ['EOI', 'name_char', 'section', 'comment'])
        eq = ln.find('=')
        if eq == -1:
            byte_pos = line_start + len(ln.encode('utf-8'))
            raise MimeappsParseFailure(byte_pos, 0, len(ln) + 1, ln, has_nl, ['name_char'])
        if eq == 0:
            raise MimeappsParseFailure(line_start, 0, 1, ln, has_nl, ['EOI', 'name_char', 'section', 'comment'])
        name = ln[:eq]
        value = ln[eq + 1:]
        for j, ch in enumerate(name):
            if not _is_name_char(ch):
                byte_pos = line_start + len(ln[:j].encode('utf-8'))
                raise MimeappsParseFailure(byte_pos, 0, j + 1, ln, has_nl, ['name_char'])
        if value == '':
            byte_pos = line_start + len(ln.encode('utf-8'))
            raise MimeappsParseFailure(byte_pos, 0, len(ln) + 1, ln, has_nl, ['value_char'])
        for j, ch in enumerate(value):
            if not _is_value_char(ch):
                byte_pos = line_start + len((ln[:eq + 1 + j]).encode('utf-8'))
                raise MimeappsParseFailure(byte_pos, 0, eq + 2 + j, ln, has_nl, ['value_char'])
        # record entry
        target = None
        if current_name == 'Default Applications':
            target = defaults
        elif current_name == 'Added Associations':
            target = added
        elif current_name == 'Removed Associations':
            target = removed
        else:
            target = None
        if target is not None:
            mk, err = parse_mime_str(name)
            if mk is None:
                continue
            tokens = value.split(';')
            uniq = []
            for t in tokens:
                if t not in uniq:
                    uniq.append(t)
            filtered = []
            for t in uniq:
                cand, entry = lookup_desktop(t)
                if entry is not None:
                    filtered.append(t)
            if filtered:
                target[mk] = filtered
            else:
                if mk in target:
                    del target[mk]
    return defaults, added

def mimeapps_panic_from_failure(text, fail):
    # recompute line number / col if needed
    # find line by searching physical lines
    phys = text.split('\n')
    # Determine line containing byte_pos roughly by iterating
    # Simpler: we stored col=0 etc for some; recompute from byte_pos
    data = text.encode('utf-8')
    upto = data[:fail.byte_pos]
    try:
        upto_text = upto.decode('utf-8')
    except Exception:
        upto_text = upto.decode('utf-8', 'replace')
    line_no = upto_text.count('\n') + 1
    last_nl = upto_text.rfind('\n')
    if last_nl == -1:
        col_no = len(upto_text) + 1
        line_text = phys[0] if phys else ''
    else:
        col_no = len(upto_text) - last_nl
        # line text is the physical line at line_no
        idx = line_no - 1
        line_text = phys[idx] if idx < len(phys) else ''
    if fail.col_no:
        col_no = fail.col_no
    # line_text from stored if available
    if fail.line_text:
        line_text = fail.line_text
    has_nl = True
    # Determine if that line had newline in source
    # If byte position points at newline char, line is terminated.
    positives_str = ', '.join(fail.positives)
    line_repr = _pest_line_repr(line_text, has_nl and not (text != '' and not text.endswith('\n') and line_no == len(phys)))
    # For no-trailing-newline case, line repr without symbol
    if text != '' and not text.endswith('\n'):
        # check whether the failing line is last line
        if line_no == len(phys):
            line_repr = _pest_line_repr(line_text, False)
    err = 'Error { variant: ParsingError { positives: [%s], negatives: [] }, location: Pos(%d), line_col: Pos((%d, %d)), path: None, line: %s, continued_line: None }' % (positives_str, fail.byte_pos, line_no, col_no, line_repr)
    panic("src/apps/user.rs:12:65", "called `Result::unwrap()` on an `Err` value: ParseApps(%s)" % err)

# wrap parse to panic
orig_parse_mimeapps_text = parse_mimeapps_text
def parse_mimeapps_text_panic(text, apps):
    try:
        return orig_parse_mimeapps_text(text, apps)
    except MimeappsParseFailure as f:
        mimeapps_panic_from_failure(text, f)
# monkey patch reference used in Apps
parse_mimeapps_text = parse_mimeapps_text_panic

