def validate_mime_value(s):
    if s.startswith('.'):
        filename = rust_path_file_name(s)
        mk = guess_mime_by_filename(filename) if filename else None
        if mk is None or mk.essence() in ('application/x-zerosize', 'application/octet-stream'):
            return "could not figure out the mime type of '%s'" % s
        return None
    mk, err = parse_mime_str(s)
    if err is not None:
        return err
    if mk is not None and mk.sub == '':
        return 'bad mime: %s' % s
    return None

def mime_from_validated(s):
    if s.startswith('.'):
        filename = rust_path_file_name(s)
        mk = guess_mime_by_filename(filename)
        return mk
    mk, _ = parse_mime_str(s)
    return mk

def validate_handler_value(s):
    cand, entry = lookup_desktop(s)
    if cand is None:
        return "no handlers found for '%s'" % s
    if entry is None:
        return 'malformed desktop entry at %s' % cand
    return None

def validate_path_value(s):
    url = parse_url(s)
    if url is not None and url.scheme == 'file' and url.file_host_bad:
        return 'Bad path: %s' % url.file_path_display
    return None

# ---------------------------------------------------------------------------
# Jaro-Winkler / suggestions

def jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0:
        return 0.0
    match_distance = max(len1, len2) // 2 - 1
    if match_distance < 0:
        match_distance = 0
    s1_matches = [False] * len1
    s2_matches = [False] * len2
    matches = 0
    for i in range(len1):
        start = max(0, i - match_distance)
        end = min(i + match_distance + 1, len2)
        for j in range(start, end):
            if s2_matches[j]:
                continue
            if s1[i] != s2[j]:
                continue
            s1_matches[i] = True; s2_matches[j] = True; matches += 1; break
    if matches == 0:
        return 0.0
    k = 0; transpositions = 0
    for i in range(len1):
        if not s1_matches[i]:
            continue
        while not s2_matches[k]:
            k += 1
        if s1[i] != s2[k]:
            transpositions += 1
        k += 1
    transpositions /= 2
    return (matches / len1 + matches / len2 + (matches - transpositions) / matches) / 3

def jaro_winkler(s1, s2):
    j = jaro(s1, s2)
    if j > 0.7:
        prefix = 0
        for i in range(min(len(s1), len(s2), 4)):
            if s1[i] == s2[i]:
                prefix += 1
            else:
                break
        j += prefix * 0.1 * (1 - j)
    return j

def did_you_mean(value, candidates):
    scored = []
    for cand in candidates:
        conf = jaro_winkler(value, cand)
        if conf > 0.8:
            scored.append((conf, cand))
    if not scored:
        return None
    scored.sort(key=lambda x: x[0], reverse=True)
    return scored[0][1]

