def bin_name():
    argv0 = sys.argv[0] if sys.argv else 'handlr'
    # basename
    base = argv0.replace('\\', '/').rstrip('/')
    if '/' in base:
        base = base.rsplit('/', 1)[-1]
    if base == '':
        base = 'handlr'
    return base

BIN = bin_name()
BIN_DASH = BIN.replace(' ', '-')
ROOT_NAME = BIN_DASH if ' ' in BIN else 'handlr'

def top_help_text():
