def normal_usage(sub):
    if sub is None:
        return "%s <SUBCOMMAND>" % BIN
    specs = {
        'list': '[FLAGS]', 'open': '<paths>...', 'set': '<mime> <handler>', 'unset': '<mime>',
        'launch': '<mime> [args]...', 'get': '[FLAGS] <mime>', 'add': '<mime> <handler>',
    }
    return "%s %s %s" % (BIN, sub, specs[sub])

def err_exit(text):
    sys.stderr.write(text)
    sys.stderr.flush()
    sys.exit(2)

def clap_error_found_argument(token_display, usage, did_you_mean_block=None):
    msg = "error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\n" % token_display
    if did_you_mean_block:
        msg += did_you_mean_block + "\n\n"
    msg += "If you tried to supply `%s` as a PATTERN use `-- %s`\n\nUSAGE:\n    %s\n\nFor more information try --help\n" % (token_display, token_display, usage)
    err_exit(msg)

def smart_usage(sub, used_flags, used_multi_optional, suggested_flag=None):
    # build usage including used flags
    parts = ["%s %s" % (BIN, sub)]
    for (name, disp, required, multiple) in POS_SPECS[sub]:
        if required:
            parts.append("<%s>%s" % (disp, '...' if multiple else ''))
        else:
            if multiple and used_multi_optional:
                parts.append("<%s>..." % disp)
            else:
                parts.append("[%s]%s" % (disp, '...' if multiple else ''))
    flags = []
    # definition order of custom flags
    for (lname, short) in FLAG_SPECS[sub]:
        if lname in used_flags:
            flags.append('--' + lname)
    if suggested_flag and ('--' + suggested_flag) not in flags and suggested_flag not in ('help', 'version'):
        # suggested custom flag
        if suggested_flag in [f[0] for f in FLAG_SPECS[sub]]:
            flags.append('--' + suggested_flag)
    if suggested_flag in ('help', 'version'):
        flags.append('--' + suggested_flag)
    if flags:
        parts.extend(flags)
    elif FLAG_SPECS[sub]:
        parts.append('[FLAGS]')
    return ' '.join(parts)

def long_flag_name(token):
    rest = token[2:]
    if '=' in rest:
        rest = rest.split('=', 1)[0]
    # clap trims leading dashes of name for display of '---' etc.
    # For typical tokens rest doesn't start with '-'. Keep as is except a name
    # that is all dashes becomes ''.
    if rest.strip('-') == '':
        # if rest starts with '-' and rest is like '-' or '--', name is ''
        if rest.startswith('-'):
            return ''
    return rest

def check_invalid_utf8_long(token_bytes):
    if token_bytes.startswith(b'--'):
        rest = token_bytes[2:]
        name_part = rest.split(b'=', 1)[0]
        try:
            name_part.decode('utf-8')
        except Exception:
            panic("/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap-3.0.0-beta.2/src/parse/parser.rs:1233:46", "unexpected invalid UTF-8 code point")

def parse_subcommand_args(sub, tokens, tokens_bytes):
    pos_specs = POS_SPECS[sub]
    flag_specs = FLAG_SPECS[sub]
    long_to_flag = {lname: lname for (lname, s) in flag_specs}
    short_to_flag = {s: lname for (lname, s) in flag_specs if s}
    values = {}  # positional name -> list of values
    flags_seen = {}
    appearance = []  # ids in first-appearance order: ('flag',name) or ('pos',name)
    def note_appearance(kind, name):
        key = (kind, name)
        if key not in appearance:
            appearance.append(key)
    i = 0
    after_dd = False
    pos_index = 0  # index into pos_specs for non-multi or current
    used_multi_optional = False
    n = len(tokens)
    while i < n:
        token = tokens[i]
        tb = tokens_bytes[i] if i < len(tokens_bytes) else token.encode()
        if not after_dd and token == '--':
            after_dd = True
            i += 1
            continue
        if not after_dd and token.startswith('--') and token != '--':
            check_invalid_utf8_long(tb)
            name = long_flag_name(token)
            disp = '--' + name
            if name == 'help':
                sys.stdout.write(sub_help_text(sub)); sys.exit(0)
            if name == 'version':
                sys.stdout.write("%s-%s \n" % (BIN_DASH, sub)); sys.exit(0)
            if name in long_to_flag:
                flags_seen[name] = flags_seen.get(name, 0) + 1
                note_appearance('flag', name)
                i += 1
                continue
            # unknown long
            candidates = [f[0] for f in flag_specs] + ['help', 'version']
            cand = did_you_mean(name, candidates)
            block = None
            sug = None
            if cand:
                sug = cand
                block = "\tDid you mean '--%s'?" % cand
            usage = smart_usage(sub, set(flags_seen.keys()), used_multi_optional, suggested_flag=sug)
            clap_error_found_argument(disp, usage, block)
        if not after_dd and token.startswith('-') and token != '-' and token != '':
            # short cluster
            chars = token[1:]
            consumed_unknown = None
            for ch in chars:
                if ch == 'h':
                    sys.stdout.write(sub_help_text(sub)); sys.exit(0)
                if ch == 'V':
                    sys.stdout.write("%s-%s \n" % (BIN_DASH, sub)); sys.exit(0)
                if ch in short_to_flag:
                    fname = short_to_flag[ch]
                    flags_seen[fname] = flags_seen.get(fname, 0) + 1
                    note_appearance('flag', fname)
                    continue
                consumed_unknown = ch
                break
            if consumed_unknown is not None:
                clap_error_found_argument('-%s' % consumed_unknown, normal_usage(sub))
            i += 1
            continue
        # positional
        # find target spec
        target = None
        if pos_index < len(pos_specs):
            target = pos_specs[pos_index]
        if target is None:
            clap_error_found_argument(token, normal_usage(sub))
        (pname, disp, required, multiple) = target
        if multiple:
            values.setdefault(pname, []).append(token)
            note_appearance('pos', pname)
            if not required:
                used_multi_optional = True
            # stay on same spec
        else:
            values.setdefault(pname, []).append(token)
            note_appearance('pos', pname)
            pos_index += 1
        i += 1
    # missing required
    missing = []
    for (pname, disp, required, multiple) in pos_specs:
        if required:
            if pname not in values or len(values.get(pname, [])) == 0:
                missing.append(disp)
    if missing:
        msg = "error: The following required arguments were not provided:\n"
        for disp in missing:
            msg += "    <%s>%s\n" % (disp, '...' if any(p[1] == disp and p[3] for p in pos_specs) else '')
        if flags_seen:
            usage = smart_usage(sub, set(flags_seen.keys()), used_multi_optional)
        else:
            usage = normal_usage(sub)
        msg += "\nUSAGE:\n    %s\n\nFor more information try --help\n" % usage
        err_exit(msg)
    # validate in appearance order
    for (kind, name) in appearance:
        if kind == 'flag':
            if flags_seen.get(name, 0) > 1:
                msg = "error: The argument '--%s' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    %s\n\nFor more information try --help\n" % (name, normal_usage(sub))
                err_exit(msg)
        else:
            # positional
            spec = [p for p in pos_specs if p[0] == name][0]
            (pname, disp, required, multiple) = spec
            vals = values.get(pname, [])
            # empty value check
            if any(v == '' for v in vals):
                disp_str = '<%s>%s' % (disp, '...' if multiple else '')
                msg = "error: The argument '%s' requires a value but none was supplied\n\nUSAGE:\n    %s\n\nFor more information try --help\n" % (disp_str, normal_usage(sub))
                err_exit(msg)
            # validator
            for v in vals:
                verr = None
                disp_name = disp
                if sub in ('set', 'unset', 'launch', 'get', 'add') and pname == 'mime':
                    verr = validate_mime_value(v)
                    disp_name = 'mime'
                elif sub in ('set', 'add') and pname == 'handler':
                    verr = validate_handler_value(v)
                    disp_name = 'handler'
                elif sub == 'open' and pname == 'paths':
                    verr = validate_path_value(v)
                    disp_name = 'paths'
                if verr is not None:
                    if multiple:
                        d = '<%s>...' % disp_name
                    else:
                        d = '<%s>' % disp_name
                    msg = "error: Invalid value for '%s': %s\n\nFor more information try --help\n" % (d, verr)
                    err_exit(msg)
    return values, flags_seen

def top_level_parse(tokens, tokens_bytes):
    if not tokens:
        # no args: help to stderr, exit 2
        sys.stderr.write(top_help_text()); sys.exit(2)
    i = 0
    after_dd = False
    while i < len(tokens):
        token = tokens[i]
        tb = tokens_bytes[i]
        if not after_dd and token == '--':
            if i == len(tokens) - 1:
                sys.stderr.write(top_help_text()); sys.exit(2)
            after_dd = True
            i += 1
            continue
        if after_dd:
            # token treated as unexpected positional at top
            clap_error_found_argument(token, normal_usage(None))
        if token.startswith('--') and token != '--':
            check_invalid_utf8_long(tb)
            name = long_flag_name(token)
            disp = '--' + name
            if name == 'help':
                sys.stdout.write(top_help_text()); sys.exit(0)
            if name == 'version':
                sys.stdout.write("%s %s\n" % (ROOT_NAME, VERSION)); sys.exit(0)
            # unknown long at top
            cand = did_you_mean(name, ['help', 'version'])
            if cand:
                block = "\tDid you mean '--%s'?" % cand
                err_exit("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\n%s\n\nIf you tried to supply `%s` as a PATTERN use `-- %s`\n\nUSAGE:\n    %s --%s\n\nFor more information try --help\n" % (disp, block, disp, disp, BIN, cand))
            # subcommand flags ?
            subflag_candidates = []
            for sname, fl in FLAG_SPECS.items():
                for (lname, sh) in fl:
                    subflag_candidates.append((lname, sname))
            best = None; best_conf = 0
            for (lname, sname) in subflag_candidates:
                conf = jaro_winkler(name, lname)
                if conf > 0.8 and conf > best_conf:
                    best_conf = conf; best = (lname, sname)
            if best:
                block = "\tDid you mean to put '--%s' after the subcommand '%s'?" % best
                err_exit("error: Found argument '%s' which wasn't expected, or isn't valid in this context\n\n%s\n\nIf you tried to supply `%s` as a PATTERN use `-- %s`\n\nUSAGE:\n    %s <SUBCOMMAND>\n\nFor more information try --help\n" % (disp, block, disp, disp, BIN))
            clap_error_found_argument(disp, normal_usage(None))
        if token.startswith('-') and token != '-' and token != '':
            for ch in token[1:]:
