            fpath = url.file_path_str
            if os.path.isdir(fpath):
                mk, _ = parse_mime_str('inode/directory')
                return (mk, fpath, fpath)
            filename = rust_path_file_name(fpath)
            mk = guess_mime_by_filename(filename)
            if mk is None:
                mk, _ = parse_mime_str('application/x-zerosize')
            return (mk, fpath, fpath)
        else:
            mk, _ = parse_mime_str('x-scheme-handler/%s' % url.scheme)
            return (mk, url_serialize(url), None)
